/* INCA STATS ANALIZADOR · V1
   CSS consolidado en el mismo orden de cascada de la última base estable.
*/

/* ===== inca-stats-v53.css ===== */

/* ======================================================================
   CONSOLIDADO DESDE: core.css
   ====================================================================== */
@charset "UTF-8";

/* ==========================================================================
   INCA STATS PRO — CORE.CSS 2026
   Hoja de estilos consolidada para index.html y escaner.js.
   Componentes organizados por módulo, sin capas correctivas al final.
   ========================================================================== */

/* GLOBALES INMUTABLES */
:root {
    --bar-green: #10b981; 
    --bar-red: #ef4444; 
    --bar-yellow: #f59e0b;
    --gold-accent: #d97706; 
    --transition-fast: 0.3s ease;
}

/* 1. MODO CLARO */
body.theme-default, body.theme-arquero, body.theme-defensor, body.theme-mediocentro, body.theme-delantero {
    --bg-deep: #f1f5f9; 
    --bg-panel: #ffffff; 
    --border-color: #cbd5e1;
    --text-primary: #0f172a; 
    --text-muted: #64748b;
    color-scheme: light;
}

body.theme-default { --brand-accent: #10b981; }
body.theme-arquero { --brand-accent: #d97706; }
body.theme-defensor { --brand-accent: #2563eb; }
body.theme-mediocentro { --brand-accent: #16a34a; }
body.theme-delantero { --brand-accent: #dc2626; }

/* 2. MODO OSCURO */
body.dark-mode.theme-default, body.dark-mode.theme-arquero, body.dark-mode.theme-defensor, body.dark-mode.theme-mediocentro, body.dark-mode.theme-delantero {
    --bg-deep: #0f172a; 
    --bg-panel: #1e293b; 
    --border-color: #334155;
    --text-primary: #f8fafc; 
    --text-muted: #94a3b8;
    color-scheme: dark;
}

body.dark-mode.theme-default { --brand-accent: #10b981; }
body.dark-mode.theme-arquero { --brand-accent: #fbbf24; }
body.dark-mode.theme-defensor { --brand-accent: #60a5fa; }
body.dark-mode.theme-mediocentro { --brand-accent: #4ade80; }
body.dark-mode.theme-delantero { --brand-accent: #f87171; }

* { margin: 0; padding: 0; box-sizing: border-box; text-transform: uppercase; }

body { 
    background-color: var(--bg-deep); 
    color: var(--text-primary); 
    font-family: 'Montserrat', sans-serif; 
    -webkit-font-smoothing: antialiased; 
    display: flex; 
    align-items: flex-start; 
    height: 100vh; 
    overflow: hidden; 
    transition: background-color 0.3s ease, color 0.3s ease;
}

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-deep); border-left: 1px solid var(--border-color); border-radius: 4px; }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 4px; transition: 0.3s;}
::-webkit-scrollbar-thumb:hover { background: var(--brand-accent); }

.app-container { display: flex; width: 100%; height: 100vh; position: relative; overflow: hidden; }
.mobile-menu-btn, .mobile-close-btn { display: none; }

.sidebar { width: 300px; background: var(--bg-panel); border-right: 1px solid var(--border-color); box-shadow: 5px 0 25px rgba(0, 0, 0, 0.1); display: flex; flex-direction: column; height: 100vh; position: fixed; z-index: 100; transition: transform 0.3s ease, background-color 0.3s ease, border-color 0.3s ease; }
.brand-header { padding: 12px 20px; border-bottom: 1px solid var(--border-color); display: flex; flex-direction: column; align-items: center; text-align: center;}
.brand-logo-container { position: relative; width: 60px; height: 60px; margin-bottom: 8px; }
.brand-logo { position: relative; width: 100%; height: 100%; border-radius: 50%; border: 3px solid var(--brand-accent); object-fit: cover; box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1); z-index: 2; }
.brand-title { font-size: 1.1rem; font-weight: 900; font-family: 'Poppins', sans-serif; letter-spacing: -0.5px; color: var(--text-primary);}
.brand-title span { color: var(--brand-accent); }
.brand-admin { font-size: 0.7rem; color: var(--text-muted); letter-spacing: 0.1em; margin-top: 2px; font-weight: 600;}
.brand-divider { height: 4px; width: 60px; background: linear-gradient(90deg, transparent, var(--brand-accent), transparent); margin-top: 10px; }

.sidebar-scroll-area { padding: 15px 20px; overflow-y: auto; flex: 1; }
.control-block { margin-bottom: 12px; }
.block-title { font-size: 11px; font-weight: 800; margin-bottom: 12px; letter-spacing: 0.15em; color: var(--brand-accent); }

.status-dot { width: 12px; height: 12px; border-radius: 50%; display: inline-block; position: relative; transition: 0.3s; flex-shrink: 0; }
.status-dot.loading { background: var(--bar-yellow); animation: pulse-yellow 1.5s infinite; }
.status-dot.ready { background: var(--brand-accent); animation: pulse-green 2s infinite; }
.status-dot.error { background: var(--bar-red); box-shadow: 0 0 8px var(--bar-red); }

@keyframes pulse-yellow { 0% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); } 70% { box-shadow: 0 0 0 6px rgba(245, 158, 11, 0); } 100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0); } }
@keyframes pulse-green { 0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); } 70% { box-shadow: 0 0 0 8px rgba(16, 185, 129, 0); } 100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); } }

.selector-group { margin-bottom: 12px; }
.selector-group label { display: block; font-size: 10px; color: var(--text-muted); margin-bottom: 6px; font-weight: 700; letter-spacing: 0.05em; }
.custom-select-wrapper { position: relative; background-color: var(--bg-deep); border: 1px solid var(--border-color); border-radius: 0.5rem; display: flex; align-items: center; transition: var(--transition-fast); }
.custom-select-wrapper:hover { border-color: var(--brand-accent); }
.custom-select-wrapper.focused { border-color: var(--brand-accent); background-color: var(--bg-panel); }
.hidden-native-select { display: none !important; appearance: none; }
.custom-display { flex: 1; display: flex; justify-content: space-between; align-items: center; padding: 0.6rem 1rem; cursor: pointer; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 700; color: var(--text-primary); }
.custom-display.numeric-input { font-size: 14px; font-weight: 900; color: var(--brand-accent); }
.custom-list { position: absolute; top: calc(100% + 8px); left: 0; width: 100%; background: var(--bg-panel); border: 1px solid var(--brand-accent); border-radius: 0.5rem; z-index: 9999; max-height: 300px; overflow-y: auto; opacity: 0; visibility: hidden; transform: translateY(-10px); transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: 0 10px 25px rgba(0,0,0,0.2); }
.custom-list::-webkit-scrollbar { width: 6px; }
.custom-list.show { opacity: 1; visibility: visible; transform: translateY(0); }
.custom-optgroup { display: flex; align-items: center; gap: 8px; padding: 10px 16px; font-family: 'Poppins', sans-serif; font-size: 11px; font-weight: 800; color: var(--text-primary); letter-spacing: 0.05em; background: var(--bg-deep); border-bottom: 1px solid var(--border-color); pointer-events: none; }
.custom-item { padding: 10px 16px; font-family: 'Montserrat', sans-serif; font-size: 10px; font-weight: 700; color: var(--text-muted); cursor: pointer; transition: 0.2s; }
.custom-item.sub-item { padding-left: 36px; position: relative; }
.custom-item.sub-item::before { content: ''; position: absolute; left: 16px; top: 50%; transform: translateY(-50%); width: 6px; height: 6px; background: var(--border-color); border-radius: 50%; transition: 0.3s; }
.custom-list.numeric-input .custom-item { font-size: 13px; font-weight: 800; }
.custom-item:hover { background: var(--bg-deep); color: var(--brand-accent); }
.custom-item.selected { color: var(--bg-deep); border-left: 3px solid var(--brand-accent); background: var(--brand-accent); font-weight: 800; }
.custom-item.sub-item.selected { padding-left: 36px; border-left: none; }
.input-icon { padding-left: 15px; font-size: 13px; color: var(--brand-accent); }
.prefix-over { font-size: 10px; font-weight: 800; padding: 0 15px; border-right: 1px solid var(--border-color); color: var(--text-muted); }

.accordion-item { border: 1px solid var(--border-color); border-radius: 0.5rem; margin-bottom: 8px; background: var(--bg-panel); overflow: hidden; transition: var(--transition-fast); box-shadow: 0 2px 6px -1px rgba(0,0,0,0.05);}
.accordion-item:hover { border-color: var(--brand-accent); }
.accordion-header { width: 100%; background: transparent; border: none; color: var(--text-primary); padding: 10px 16px; font-size: 11px; font-weight: 800; cursor: pointer; display: flex; justify-content: space-between; align-items: center; letter-spacing: 0.05em; transition: var(--transition-fast); flex-wrap: nowrap; }
.accordion-header:hover { background: var(--bg-deep); color: var(--brand-accent); }
.header-left { display: flex; align-items: center; white-space: nowrap; overflow: hidden; }
.header-left span { white-space: nowrap; } 
.header-left i { color: var(--brand-accent); background: var(--bg-deep); padding: 6px; border-radius: 6px; font-size: 12px; margin-right: 10px; flex-shrink: 0; }
.accordion-content { display: none; border-top: 1px solid var(--border-color); background: var(--bg-deep); }
.menu-option { padding: 10px 16px 10px 42px; font-size: 10px; font-weight: 700; color: var(--text-muted); cursor: pointer; transition: var(--transition-fast); white-space: nowrap; }
.menu-option:hover { color: var(--brand-accent); background: var(--bg-panel); padding-left: 48px; }
.menu-option.active { color: var(--bg-panel); background: var(--brand-accent); border-left: 4px solid var(--text-primary); font-weight: 900; padding-left: 40px; }

.main-content { flex: 1; margin-left: 300px; padding: 20px; display: flex; flex-direction: column; gap: 20px; transition: margin 0.3s ease; height: 100vh; overflow-y: auto; overflow-x: hidden; padding-bottom: 50px; }
.editor-panel-style { background: var(--bg-panel); border: 1px solid var(--border-color); box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1); border-radius: 1rem; transition: background-color 0.3s, border-color 0.3s;}

.top-bar { display: flex; flex-wrap: wrap; gap: 20px; align-items: center; position: relative; z-index: 50; background: var(--bg-panel); padding: 20px 24px; border-radius: 1rem; border: 1px solid var(--border-color); transition: background-color 0.3s, border-color 0.3s; }

.theme-toggle-btn { background: transparent; border: 1px solid var(--border-color); color: var(--text-primary); width: 38px; height: 38px; border-radius: 50%; cursor: pointer; display: flex; justify-content: center; align-items: center; transition: all 0.3s ease; font-size: 14px; flex-shrink: 0; }
.theme-toggle-btn:hover { background: var(--bg-deep); color: var(--brand-accent); border-color: var(--brand-accent); transform: rotate(15deg); }

.filter-group { display: flex; flex-direction: column; gap: 8px; flex: 1; min-width: 220px; }
.filter-group label { display: block; font-size: 11px; font-weight: 800; letter-spacing: 0.05em; color: var(--text-muted); }
.input-logo { width: 34px; height: 34px; object-fit: contain; margin-left: 12px; filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.2)); }
.team-logo { width: 28px; height: 28px; object-fit: contain; vertical-align: middle; margin-right: 10px; filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.2)); transition: transform 0.3s ease; }
.data-table tr:hover .team-logo { transform: scale(1.1) rotate(2deg); }

.results-section { position: relative; z-index: 10; display: flex; flex-direction: column; gap: 20px; }
.summary-hud { padding: 24px; display: grid; grid-template-columns: 1fr auto; grid-template-areas: "info filters"; gap: 15px 30px; align-items: center; }
.hud-info { grid-area: info; display: flex; flex-direction: column; justify-content: center; }
.hud-title { font-size: 24px; font-weight: 900; letter-spacing: 0.05em; margin-bottom: 4px; color: var(--brand-accent); font-family: 'Poppins', sans-serif;}
.hud-subtitle { font-size: 10px; font-weight: 700; letter-spacing: 0.1em; color: var(--text-primary); background: var(--bg-deep); padding: 4px 12px; border-radius: 4px; width: fit-content; display: inline-block;}
.hud-filters { grid-area: filters; display: flex; gap: 15px; align-items: flex-end; justify-self: end; }
.stat-hit-text { color: var(--brand-accent); }
.stat-miss-text { color: var(--bar-red); font-size: 13px; }
.split-tables-container { display: grid; grid-template-columns: repeat(auto-fit, minmax(400px, 1fr)); gap: 20px; width: 100%; }
.split-tables-container.single-column { grid-template-columns: 1fr; }
.table-header-title { padding: 14px 20px; font-size: 12px; font-weight: 900; color: var(--text-primary); border-bottom: 1px solid var(--border-color); background: var(--bg-deep); border-radius: 1rem 1rem 0 0; display: flex; align-items: center; gap: 10px; letter-spacing: 0.05em; transition: background-color 0.3s;}
.home-title i { color: var(--brand-accent); font-size: 14px;}
.away-title i { color: var(--gold-accent); font-size: 14px;}
.table-container { overflow-x: auto; border-radius: 0 0 1rem 1rem; border-top: none; }
.data-table { width: 100%; border-collapse: collapse; text-align: left; min-width: 100%; } 
.data-table th { padding: 12px 8px; font-size: 10px; font-weight: 800; color: var(--text-muted); letter-spacing: 0.05em; border-bottom: 1px solid var(--border-color); background: var(--bg-deep); }
.data-table td { padding: 12px 8px; font-size: 11px; font-weight: 700; border-bottom: 1px solid var(--border-color); vertical-align: middle; transition: background 0.3s ease; color: var(--text-primary); }
.data-table td:not(:first-child), .data-table th:not(:first-child) { text-align: center; }
.col-value, .col-rival-val, .col-total { font-family: 'Montserrat', sans-serif; font-size: 15px; font-weight: 900 !important; color: var(--text-primary) !important; }

.row-hit td { background-color: rgba(16, 185, 129, 0.12) !important; color: var(--text-primary); border-bottom: 1px solid rgba(16, 185, 129, 0.2) !important;}
.row-miss td { background-color: rgba(239, 68, 68, 0.08) !important; color: var(--text-primary); border-bottom: 1px solid rgba(239, 68, 68, 0.2) !important;}
.row-hit td:first-child { border-left: 4px solid var(--bar-green); }
.row-miss td:first-child { border-left: 4px solid var(--bar-red); }

/* VISTA 2: BASE DE DATOS PRO */
.db-hero { padding: 20px 24px; display: flex; flex-direction: column; gap: 15px; }
.db-split-filters { display: flex; gap: 1px; background: var(--border-color); border-radius: 8px; overflow: hidden; width: fit-content; }
.db-split-btn { background: var(--bg-deep); border: none; padding: 10px 24px; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 800; color: var(--text-muted); cursor: pointer; transition: 0.2s; letter-spacing: 0.05em;}
.db-split-btn:hover { background: var(--border-color); color: var(--text-primary); }
.db-split-btn.active { background: var(--brand-accent); color: var(--bg-deep); box-shadow: inset 0 -3px 0 rgba(0,0,0,0.1); }

.db-market-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; padding-bottom: 12px; border-bottom: 2px solid var(--bg-deep); }
.db-market-btn { background: transparent; border: 1px solid var(--border-color); padding: 10px 20px; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 700; color: var(--text-muted); cursor: pointer; border-radius: 6px; transition: 0.2s; letter-spacing: 0.05em; text-transform: uppercase;}
.db-market-btn:hover { background: var(--border-color); color: var(--text-primary); }
.db-market-btn.active { background: var(--brand-accent); color: var(--bg-deep); border-color: var(--brand-accent); font-weight: 900;}

.db-pro-btn { width: 100%; background: var(--bg-deep); color: var(--brand-accent); border: 1px solid var(--brand-accent); padding: 12px 16px; border-radius: 0.5rem; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 800; cursor: pointer; transition: 0.3s; display: flex; align-items: center; justify-content: center; gap: 10px; letter-spacing: 0.1em; }
.db-pro-btn:hover { background: var(--brand-accent); color: var(--bg-deep); transform: translateY(-2px); }
.db-pro-btn-back { background: var(--bg-deep); color: var(--text-primary); border: 1px solid var(--border-color); padding: 12px 20px; border-radius: 0.5rem; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 800; cursor: pointer; transition: 0.3s; display: flex; align-items: center; gap: 10px; letter-spacing: 0.05em; height: 44px; }
.db-pro-btn-back:hover { background: var(--border-color); color: var(--brand-accent); }

.ac-table-wrapper { background: var(--bg-panel); border-radius: 1rem; border: 1px solid var(--border-color); overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); margin-bottom: 20px;}
.ac-table-header { background: var(--bg-deep); padding: 14px 20px; font-family: 'Poppins', sans-serif; font-size: 13px; font-weight: 900; color: var(--brand-accent); border-bottom: 1px solid var(--border-color); text-transform: uppercase;}
.ac-table { width: 100%; border-collapse: collapse; text-align: left; }
.ac-table th { padding: 10px 20px; font-size: 10px; font-weight: 800; color: var(--text-muted); letter-spacing: 0.1em; border-bottom: 1px solid var(--border-color); background: var(--bg-panel); text-transform: uppercase; }
.ac-table td { padding: 10px 20px; font-size: 11px; font-weight: 700; border-bottom: 1px solid var(--border-color); color: var(--text-primary); vertical-align: middle; }
.ac-table tr:hover td { background: var(--bg-deep); }

.ac-bar-bg { width: 100%; height: 20px; background: var(--bg-deep); border: 1px solid var(--border-color); border-radius: 6px; overflow: hidden; position: relative; }
.ac-bar-fill { height: 100%; background: var(--brand-accent); display: flex; align-items: center; padding-left: 10px; color: var(--bg-deep); font-size: 10px; font-weight: 900; font-family: 'Montserrat', sans-serif; transition: width 0.5s ease; }
.ac-bar-bg.low .ac-bar-fill { background: var(--bar-red); color: #fff;}

.table-maestra-container { background: var(--bg-panel); border-radius: 12px; border: 1px solid var(--border-color); overflow: visible; box-shadow: 0 4px 6px rgba(0,0,0,0.1); margin-bottom: 20px;}
.table-maestra-header { background: var(--bg-deep); color: var(--text-primary); padding: 14px 20px; font-family: 'Poppins', sans-serif; font-weight: 900; font-size: 12px; letter-spacing: 0.05em; border-bottom: 1px solid var(--border-color); border-radius: 12px 12px 0 0;}
.tm-table { width: 100%; border-collapse: collapse; text-align: center; }
.tm-table th { padding: 8px 6px; font-size: 10px; font-weight: 800; background: var(--bg-panel); color: var(--text-muted); border-bottom: 1px solid var(--border-color); letter-spacing: 0.05em;}
.tm-table td { padding: 8px 6px; font-size: 11px; font-weight: 800; border-bottom: 1px solid var(--border-color); color: var(--text-primary); vertical-align: middle;}
.tm-table tr:hover td { background: var(--bg-deep); }

.col-rank { font-weight: 900 !important; color: var(--text-muted) !important; border-left: 4px solid transparent;}
.col-pts { color: var(--brand-accent) !important; font-weight: 900 !important; font-size: 13px !important;}
.league-row-selected { background-color: var(--bg-deep) !important; border-left: 3px solid var(--brand-accent);}

.matrix-res-box { position: relative; display: inline-flex; justify-content: center; align-items: center; padding: 6px 10px; border-radius: 4px; font-size: 12px; font-weight: 700; font-family: 'Montserrat', sans-serif; cursor: pointer; width: 100%; min-width: 70px;}
.matrix-empty { display: inline-flex; justify-content: center; align-items: center; padding: 6px 10px; border-radius: 4px; width: 100%; min-width: 70px; font-weight: 700; background: var(--bg-deep); color: var(--text-muted);}

.matrix-res-box .custom-tooltip { visibility: hidden; opacity: 0; position: absolute; bottom: 130%; left: 50%; transform: translateX(-50%); background-color: #0f172a; color: #ffffff; text-align: center; padding: 8px 12px; border-radius: 8px; font-size: 10px; font-weight: 700; letter-spacing: 0.05em; white-space: nowrap; z-index: 9999; transition: all 0.2s ease; box-shadow: 0 4px 10px rgba(0,0,0,0.15); pointer-events: none; line-height: 1.5;}
.matrix-res-box .custom-tooltip::after { content: ""; position: absolute; top: 100%; left: 50%; margin-left: -5px; border-width: 5px; border-style: solid; border-color: #0f172a transparent transparent transparent;}
.matrix-res-box:hover .custom-tooltip { visibility: visible; opacity: 1; bottom: 145%; }

.res-win { background-color: #dcfce7; color: #166534; } 
.res-draw { background-color: #f1f5f9; color: #64748b; }
.res-loss { background-color: #fee2e2; color: #991b1b; } 

.zone-ucl { border-left-color: #3b82f6 !important; }
.zone-uel { border-left-color: #f59e0b !important; }
.zone-conf { border-left-color: #10b981 !important; } 
.zone-rel { border-left-color: #ef4444 !important; }

.league-legend { display: flex; gap: 15px; padding: 12px 20px; background: var(--bg-panel); border-top: 1px solid var(--border-color); font-size: 10px; font-weight: 800; color: var(--text-muted); flex-wrap: wrap; border-radius: 0 0 12px 12px;}
.leg-item { display: flex; align-items: center; gap: 6px; letter-spacing: 0.05em;}
.leg-box { width: 12px; height: 12px; border-radius: 4px; }
.leg-box.ucl { background: #3b82f6; }
.leg-box.uel { background: #f59e0b; }
.leg-box.conf { background: #10b981; }
.leg-box.rel { background: #ef4444; }


/* ==========================================================================
   MÓDULO PLAYER PROPS VIP
   ========================================================================== */
.player-control-panel { display: flex; flex-direction: column; gap: 15px; padding: 20px 24px; margin-bottom: 20px;}

.player-categories { display: flex; justify-content: center; gap: 12px; margin-bottom: 10px; padding-bottom: 15px; border-bottom: 1px solid var(--border-color); flex-wrap: wrap; }
.category-btn { background: var(--bg-deep); border: 1px solid var(--border-color); color: var(--text-muted); padding: 8px 24px; border-radius: 30px; font-size: 11px; font-weight: 800; cursor: pointer; transition: all 0.3s ease; display: flex; align-items: center; justify-content: center; gap: 8px; flex: none; }
.category-btn:hover { background: var(--border-color); color: var(--text-primary); }
.category-btn.active { background: var(--brand-accent); color: var(--bg-panel); border-color: var(--brand-accent); }
.theme-default .category-btn.active { color: #fff; }

.player-filters-row { display: flex; flex-wrap: wrap; gap: 15px; width: 100%; align-items: center; }
.filter-group-pj { flex: 1; min-width: 200px; display: flex; flex-direction: column; gap: 6px;}
.filter-group-pj label { font-size: 10px; font-weight: 800; color: var(--text-muted); letter-spacing: 0.05em; margin-left: 4px;}

.player-hero-bg { background: linear-gradient(135deg, var(--bg-panel) 0%, var(--bg-deep) 100%); border-bottom: 3px solid var(--brand-accent); transition: 0.4s; }
.player-avatar-pro { width: 85px; height: 85px; border-radius: 50%; background: var(--bg-deep); border: 3px solid var(--brand-accent); display: flex; align-items: center; justify-content: center; font-size: 30px; color: var(--text-muted); box-shadow: 0 0 15px var(--border-color); overflow: hidden; transition: 0.4s; }
.pj-bio-tag { font-size: 10px; font-weight: 800; background: var(--bg-deep); color: var(--text-primary); padding: 4px 10px; border-radius: 6px; border: 1px solid var(--border-color); display: flex; align-items: center; gap: 5px; text-transform: uppercase; transition: 0.4s;}
.pos-tag { background: var(--bg-deep); color: var(--brand-accent); border-color: var(--brand-accent); }

.high-res-avatar { image-rendering: -webkit-optimize-contrast; image-rendering: high-quality; }

.pro-search-box { flex: 2; min-width: 250px; position: relative; display: flex; align-items: center; }
.search-icon-floating { position: absolute; left: 16px; color: var(--brand-accent); font-size: 16px; z-index: 2; pointer-events: none;}
.pro-search-input { width: 100%; padding: 12px 20px 12px 45px; font-family: 'Montserrat', sans-serif; font-size: 13px; font-weight: 900; border: 1px solid var(--border-color); border-radius: 8px; background: var(--bg-deep); color: var(--brand-accent); transition: 0.3s; text-transform: uppercase; outline: none; }
.pro-search-input::placeholder { color: var(--text-muted); font-weight: 700; opacity: 0.6; }
.pro-search-input:focus { border-color: var(--brand-accent); background: var(--bg-panel); }
.pro-search-results { position: absolute; top: calc(100% + 8px); left: 0; width: 100%; background: var(--bg-panel); border: 1px solid var(--brand-accent); border-radius: 8px; box-shadow: 0 10px 30px rgba(0,0,0,0.2); z-index: 1000; max-height: 250px; overflow-y: auto; opacity: 0; visibility: hidden; transition: all 0.2s ease; transform: translateY(-5px);}
.pro-search-box.focused .pro-search-results { opacity: 1; visibility: visible; transform: translateY(0); }
.pro-search-results::-webkit-scrollbar { width: 6px; }
.pro-search-item { padding: 14px 20px; font-family: 'Montserrat', sans-serif; font-size: 12px; font-weight: 800; color: var(--text-primary); cursor: pointer; border-bottom: 1px solid var(--border-color); transition: 0.2s; display: flex; align-items: center; gap: 10px; }
.pro-search-item:hover { background: var(--bg-deep); color: var(--brand-accent); padding-left: 25px; border-left: 4px solid var(--brand-accent); }

.badge-condicion { padding: 5px 10px; border-radius: 6px; font-size: 9px; font-weight: 900; letter-spacing: 0.05em; text-transform: uppercase;}
.badge-local { background: var(--bg-deep); color: #3b82f6; border: 1px solid #bfdbfe; }
.badge-visita { background: var(--bg-deep); color: var(--bar-yellow); border: 1px solid var(--border-color); }
.badge-neutro { background: var(--bg-deep); color: var(--text-muted); border: 1px solid var(--border-color); }

/* ==========================================================================
   ARREGLO DEFINITIVO: TARJETAS DE JUGADOR (CERO TILTEO / FLICKER)
   ========================================================================== */
.player-stats-grid { 
    display: grid; 
    grid-template-columns: repeat(auto-fit, minmax(135px, 1fr)); 
    gap: 15px; 
    margin-bottom: 30px; 
    align-items: stretch; 
}

.pj-stat-card { 
    position: relative; 
    border-radius: 14px; 
    overflow: hidden; 
    background-size: cover; 
    background-position: center; 
    background-repeat: no-repeat; 
    min-height: 125px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    cursor: pointer; 
    
    /* 1. SE SECUESTRA EL TAMAÑO: No usamos border (que suma pixeles), usamos sombra interior */
    box-shadow: inset 0 0 0 0px transparent, 0 6px 15px rgba(0,0,0,0.15);
    
    /* 2. ACELERACIÓN HARDWARE */
    transform: translateZ(0); 
    
    /* 3. SOLO TRANSICIÓN EN LUCES Y SOMBRAS (Sin saltos de posición) */
    transition: box-shadow 0.2s ease, filter 0.2s ease; 
}

/* 4. BLOQUEO DE EVENTOS: Evita que el mouse se confunda al tocar el texto */
.pj-stat-overlay, .pj-stat-content {
    pointer-events: none;
}

.pj-stat-overlay { 
    position: absolute; top: 0; left: 0; right: 0; bottom: 0; 
    background: rgba(15, 23, 42, 0.82); 
    transition: background 0.3s ease; 
    z-index: 1; 
}

.pj-stat-card:hover { 
    box-shadow: inset 0 0 0 2px var(--brand-accent), 0 10px 25px rgba(0,0,0,0.3); 
    filter: brightness(1.15); 
}

.pj-stat-card:hover .pj-stat-overlay { 
    background: rgba(15, 23, 42, 0.4); 
}

/* ESTADO ACTIVO - INAMOVIBLE */
.pj-card-active {
    box-shadow: inset 0 0 0 3px var(--brand-accent), 0 10px 25px rgba(16, 185, 129, 0.3) !important;
    filter: brightness(1.15);
    z-index: 10;
}

.pj-card-active .pj-stat-overlay { background: rgba(15, 23, 42, 0.2) !important; }
.pj-card-active .pj-stat-title, 
.pj-card-active .pj-stat-avg {
    color: var(--brand-accent) !important;
    text-shadow: 0 2px 4px rgba(0,0,0,0.9);
}

.pj-stat-content { position: relative; z-index: 2; text-align: center; padding: 15px 10px; width: 100%; }
.pj-stat-title { font-size: 11px; font-weight: 900; color: #f8fafc; letter-spacing: 0.1em; margin-bottom: 6px; text-shadow: 0 2px 4px rgba(0,0,0,0.9); text-transform: uppercase; }
.pj-stat-avg { font-size: 30px; font-weight: 900; font-family: 'Poppins', sans-serif; line-height: 1; margin-bottom: 4px; text-shadow: 0 2px 6px rgba(0,0,0,0.9); }
.pj-stat-label { font-size: 9px; font-weight: 800; color: #cbd5e1; letter-spacing: 0.05em; text-shadow: 0 1px 3px rgba(0,0,0,0.9); }

.odds-premium-bar { background: var(--bg-panel); border: 1px solid var(--border-color); border-radius: 12px; margin-bottom: 25px; display: flex; flex-wrap: wrap; align-items: center; padding: 15px 20px; gap: 20px; }
.odds-bar-section { flex: 1; min-width: 200px; display: flex; flex-direction: column; gap: 6px; }
.odds-bar-section label { font-size: 10px; font-weight: 800; color: var(--brand-accent); letter-spacing: 0.05em; }
.odds-bar-results { flex: 2; min-width: 300px; background: var(--bg-deep); border-radius: 10px; padding: 15px 20px; display: flex; flex-direction: column; gap: 8px; border: 1px dashed var(--brand-accent); }
.odds-hit-rate { display: flex; justify-content: space-between; align-items: baseline; }
.hit-number { font-size: 24px; font-weight: 900; color: var(--brand-accent); font-family: 'Poppins', sans-serif; line-height: 1; }
.hit-label { font-size: 10px; font-weight: 800; color: var(--text-muted); letter-spacing: 0.1em; }
.odds-progress-container { width: 100%; height: 10px; background: var(--bg-panel); border: 1px solid var(--border-color); border-radius: 10px; overflow: hidden; }
.odds-bar-hit { height: 100%; background: var(--brand-accent); transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1); }
.odds-fraction-text { text-align: right; font-size: 10px; font-weight: 800; color: var(--text-primary); letter-spacing: 0.05em; }

#pjOddsControls .custom-list { z-index: 10000; border: 1px solid var(--brand-accent); }
#pjOddsControls .custom-display { background: var(--bg-panel); border-radius: 8px; }

/* AJUSTES A LA TABLA DE JUGADORES PARA MOSTRAR TORNEOS LARGOS */
.player-log-table th { padding: 14px 10px !important; border-bottom: 2px solid var(--border-color); }
.player-log-table td { padding: 12px 10px !important; font-family: 'Montserrat', sans-serif; font-size: 12px; border-bottom: 1px solid var(--bg-deep);}

.col-torneo-text {
    font-size: 10px; 
    font-weight: 800; 
    color: var(--text-muted); 
    white-space: normal; 
    word-break: break-word;
    max-width: 140px; 
    line-height: 1.3;
}

@keyframes pulse-glow {
    0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); border-color: var(--brand-accent); }
    70% { box-shadow: 0 0 0 10px rgba(16, 185, 129, 0); border-color: rgba(16, 185, 129, 0.5); }
    100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); border-color: var(--brand-accent); }
}
.value-bet-active { animation: pulse-glow 2s infinite; border: 2px solid var(--brand-accent) !important; }
.value-bet-badge { background: linear-gradient(135deg, var(--gold-accent), var(--bar-red)); color: #fff; padding: 4px 10px; border-radius: 6px; font-size: 10px; font-weight: 900; letter-spacing: 0.1em; display: inline-flex; align-items: center; gap: 5px;}

/* RESPONSIVE */
body.pro-mode .sidebar { display: none !important; }
body.pro-mode .main-content { margin-left: 0 !important; width: 100% !important; max-width: 100% !important; }

@media (max-width: 1400px) {
    .db-split-layout { flex-direction: column; }
}

