    box-shadow: 0 8px 22px rgba(15, 23, 42, .08);
    overflow: visible;
}
.rk-pro-filterbar .rk-select-group label {
    color: var(--text-muted);
}
.rk-pro-filterbar .rk-custom-wrapper {
    background: var(--bg-deep);
    border-color: var(--border-color);
}
.rk-pro-filterbar .rk-custom-wrapper .custom-display,
.rk-pro-filterbar .rk-custom-wrapper .modern-input {
    color: var(--text-primary);
}

.rk-search-group {
    position: relative;
    min-width: 0;
}
.rk-search-group .pro-search-box {
    width: 100%;
}
.rk-search-group .pro-search-input {
    height: 42px;
    padding: 0 14px 0 39px;
    border-radius: 10px;
    border: 1px solid var(--border-color);
    background: var(--bg-deep);
    color: var(--text-primary);
    font-size: 10px;
    font-family: 'Montserrat', sans-serif;
    font-weight: 800;
}
.rk-search-group .pro-search-input:focus {
    border-color: var(--rk-theme);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--rk-theme) 16%, transparent);
}
.rk-search-group .search-icon-floating {
    color: var(--rk-theme);
}

.rk-theme-toggle {
    width: 44px;
    height: 42px;
    margin: 0;
    align-self: end;
    border-radius: 10px;
}
.rk-pro-hero {
    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-columns: 62px minmax(0, 1fr) auto 118px;
    align-items: center;
    gap: 18px;
    min-width: 0;
    min-height: 132px;
    padding: 22px 24px;
    overflow: hidden;
    border-radius: 18px;
    border: 1px solid color-mix(in srgb, var(--rk-theme) 42%, var(--border-color));
    background:
        radial-gradient(circle at 88% 20%, color-mix(in srgb, var(--rk-theme) 23%, transparent), transparent 34%),
        linear-gradient(135deg, var(--bg-panel), color-mix(in srgb, var(--bg-deep) 72%, var(--bg-panel)));
    box-shadow: 0 12px 30px rgba(15, 23, 42, .09);
}
.rk-pro-hero::before {
    content: '';
    position: absolute;
    inset: 0 auto 0 0;
    width: 5px;
    background: var(--rk-theme);
}
.rk-pro-hero__icon {
    width: 62px;
    height: 62px;
    display: grid;
    place-items: center;
    border-radius: 17px;
    background: var(--rk-theme);
    color: #fff;
    font-size: 23px;
    box-shadow: 0 12px 25px color-mix(in srgb, var(--rk-theme) 32%, transparent);
}
.rk-pro-hero__copy {
    min-width: 0;
}
.rk-pro-hero__icon,
.rk-pro-hero__copy,
.rk-pro-hero__meta {
    position: relative;
    z-index: 1;
}
.rk-pro-hero__eyebrow {
    color: var(--rk-theme);
    font-size: 9px;
    font-weight: 900;
    letter-spacing: .16em;
}
.rk-pro-hero h3 {
    margin: 5px 0 4px;
    color: var(--text-primary);
    font-family: 'Poppins', sans-serif;
    font-size: clamp(20px, 2.5vw, 30px);
    line-height: 1.05;
    letter-spacing: -.025em;
    white-space: normal;
}
.rk-pro-hero p {
    max-width: 760px;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    line-height: 1.45;
    text-transform: none;
}
.rk-pro-hero__meta {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 6px;
    text-align: right;
}
.rk-pro-hero__meta span {
    padding: 7px 10px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--rk-theme) 13%, var(--bg-deep));
    border: 1px solid color-mix(in srgb, var(--rk-theme) 35%, var(--border-color));
    color: var(--rk-theme);
    font-size: 9px;
    font-weight: 900;
}
.rk-pro-hero__meta small {
    color: var(--text-muted);
    font-size: 8px;
    font-weight: 800;
    letter-spacing: .08em;
}
.rk-pro-hero__visual {
    position: relative;
    z-index: 0;
    justify-self: end;
    color: color-mix(in srgb, var(--rk-theme) 25%, transparent);
    font-size: 88px;
    line-height: 1;
    transform: rotate(-12deg);
}
.rk-main-card {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    margin: 0;
    overflow: hidden;
    border-radius: 16px;
    background: var(--bg-panel);
    border: 1px solid var(--border-color);
    box-shadow: 0 12px 30px rgba(15, 23, 42, .08);
}
.rk-table-scroll {
    width: 100%;
    max-width: 100%;
    overflow: hidden;
}
.rk-table {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    border-spacing: 0;
}
.rk-table th,
.rk-table td {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}
.rk-table th {
    height: 45px;
    padding: 9px 10px;
    background: var(--bg-deep);
    border-bottom: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 9px;
    font-weight: 900;
    letter-spacing: .08em;
    text-align: center;
}
.rk-table th:nth-child(1), .rk-table td:nth-child(1) { width: 6%; }
.rk-table th:nth-child(2), .rk-table td:nth-child(2) { width: 46%; text-align: left; }
.rk-table th:nth-child(3), .rk-table td:nth-child(3) { width: 9%; }
.rk-table th:nth-child(4), .rk-table td:nth-child(4) { width: 13%; }
.rk-table th:nth-child(5), .rk-table td:nth-child(5) { width: 13%; }
.rk-table th:nth-child(6), .rk-table td:nth-child(6) { width: 13%; }
.rk-table th.is-active {
    color: var(--rk-theme);
    box-shadow: inset 0 -3px 0 var(--rk-theme);
}
.rk-table td {
    padding: 9px 10px;
    border-bottom: 1px solid var(--border-color);
    background: var(--bg-panel);
    color: var(--text-primary);
    font-size: 11px;
    font-weight: 800;
    text-align: center;
    transition: background .18s ease, box-shadow .18s ease;
}
.rk-player-row {
    cursor: pointer;
    outline: none;
}
.rk-player-row:hover td,
.rk-player-row:focus-visible td {
    background: color-mix(in srgb, var(--rk-theme) 7%, var(--bg-panel));
}
.rk-player-row:hover td:first-child,
.rk-player-row:focus-visible td:first-child {
    box-shadow: inset 4px 0 0 var(--rk-theme);
}
.rk-player-info {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 12px;
}
.rk-avatar {
    position: relative;
    width: 46px;
    height: 46px;
    flex: 0 0 46px;
    overflow: hidden;
    border-radius: 13px;
    background: var(--bg-deep);
    border: 1px solid color-mix(in srgb, var(--rk-theme) 38%, var(--border-color));
    display: grid;
    place-items: center;
}
.rk-avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center 10%;
}
.rk-avatar-placeholder,
.modal-avatar-placeholder {
    position: absolute;
    inset: 0;
    display: none;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    background: var(--bg-deep);
}
.rk-player-text {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.rk-name {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-primary);
    font-size: 13px;
    font-weight: 900;
    text-transform: none;
}
.rk-team {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 6px;
    color: var(--text-muted);
    font-size: 9px;
    font-weight: 800;
    text-transform: none;
}
.rk-team-logo {
    width: 17px;
    height: 17px;
    flex: 0 0 17px;
    object-fit: contain;
}
.rk-team-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.rk-position {
    flex: 0 0 auto;
    padding-left: 7px;
    border-left: 1px solid var(--border-color);
    color: var(--rk-theme);
    white-space: nowrap;
}
.rk-number-box,
.rk-stat-normal,
.rk-stat-muted {
    font-variant-numeric: tabular-nums;
}
.rk-number-box {
    width: 29px;
    height: 29px;
    margin: auto;
    display: grid;
    place-items: center;
    border-radius: 9px;
    background: var(--bg-deep);
    color: var(--text-muted);
    font-family: 'Poppins', sans-serif;
    font-size: 11px;
    font-weight: 900;
}
.rk-number-box-total,
.rk-badge-promedio {
    min-width: 58px;
    min-height: 31px;
    padding: 5px 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    border-radius: 9px;
    font-family: 'Poppins', sans-serif;
    font-size: 11px;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
}
.rk-number-box-total {
    background: var(--bg-deep);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
}
.rk-badge-promedio {
    background: color-mix(in srgb, var(--rk-theme) 12%, var(--bg-deep));
    border: 1px solid color-mix(in srgb, var(--rk-theme) 38%, var(--border-color));
    color: var(--rk-theme);
}
.rk-status-row td {
    padding: 0;
}
.rk-status-message,
.rk-empty-state {
    min-height: 190px;
    padding: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    color: var(--text-muted);
    text-align: center;
}
.rk-empty-state {
    flex-direction: column;
}
.rk-empty-state i {
    width: 52px;
    height: 52px;
    display: grid;
    place-items: center;
    border-radius: 15px;
    background: color-mix(in srgb, var(--rk-theme) 12%, var(--bg-deep));
    color: var(--rk-theme);
    font-size: 20px;
}
.rk-empty-state strong {
    color: var(--text-primary);
    font-size: 12px;
}
.rk-empty-state span {
    max-width: 480px;
    font-size: 10px;
    line-height: 1.5;
    text-transform: none;
}
.rk-empty-state--error i,
.rk-empty-state--error strong {
    color: var(--bar-red);
}

/* Modal profesional del jugador */
.pro-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 200000;
    display: none;
    align-items: center;
    justify-content: center;
    padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
    background: rgba(2, 6, 23, .76);
    backdrop-filter: blur(8px);
    overflow-y: auto;
}
.pro-modal-content--player {
    position: relative;
    width: min(790px, 96vw);
    max-width: 790px;
    max-height: calc(100dvh - 36px);
    overflow: auto;
    border-radius: 24px;
    background: var(--bg-panel);
    border: 1px solid color-mix(in srgb, var(--rk-theme, var(--brand-accent)) 46%, var(--border-color));
    box-shadow: 0 28px 75px rgba(2, 6, 23, .48);
}
.pro-modal-close {
    position: absolute;
    top: 16px;
    right: 16px;
    z-index: 3;
    width: 40px;
    height: 40px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255,255,255,.24);
    border-radius: 12px;
    background: rgba(15, 23, 42, .44);
    color: #fff;
    cursor: pointer;
}
.pro-modal-close:hover {
    background: var(--bar-red);
}
.pro-modal-header--player {
    position: relative;
    min-height: 215px;
    padding: 34px 72px 34px 36px;
    display: grid;
    grid-template-columns: 154px minmax(0, 1fr);
    align-items: center;
    gap: 28px;
    overflow: hidden;
    background:
        radial-gradient(circle at 92% 10%, color-mix(in srgb, var(--rk-theme, #3b82f6) 44%, transparent), transparent 38%),
        linear-gradient(135deg, var(--rk-theme, #3b82f6), #0f172a 68%);
}
.pro-modal-header--player::after {
    content: '';
    position: absolute;
    right: -75px;
    bottom: -150px;
    width: 310px;
    height: 310px;
    border-radius: 50%;
    border: 45px solid rgba(255,255,255,.055);
}
.modal-avatar-wrapper--pro {
    position: relative;
    z-index: 1;
    width: 154px;
    height: 154px;
    overflow: hidden;
    border-radius: 24px;
    border: 4px solid #fff;
    background: #0f172a;
    box-shadow: 0 0 0 7px rgba(255,255,255,.12), 0 20px 38px rgba(0,0,0,.32);
}
.modal-avatar-wrapper--pro img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center 10%;
}
.modal-avatar-wrapper--pro .modal-avatar-placeholder {
    background: #0f172a;
    color: #94a3b8;
    font-size: 34px;
}
.modal-info-pj {
    position: relative;
    z-index: 1;
    min-width: 0;
}
.modal-profile-kicker,
.modal-section-eyebrow {
    color: rgba(255,255,255,.72);
    font-size: 9px;
    font-weight: 900;
    letter-spacing: .14em;
}
.modal-name {
    margin: 8px 0 12px;
    color: #fff;
    font-family: 'Poppins', sans-serif;
    font-size: clamp(27px, 4vw, 40px);
    line-height: 1.02;
    letter-spacing: -.035em;
    text-transform: none;
}
.modal-identity-row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 9px;
}
.modal-team-row,
.modal-position-pill {
    min-height: 34px;
    padding: 7px 11px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border-radius: 999px;
    background: rgba(2, 6, 23, .42);
    border: 1px solid rgba(255,255,255,.15);
    color: #fff;
    font-size: 9px;
    font-weight: 900;
}
.modal-team-logo {
    width: 20px;
    height: 20px;
    object-fit: contain;
}
.pro-modal-body {
    padding: 28px 32px 32px;
    background: var(--bg-panel);
}
.modal-section-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 15px;
}
.modal-section-eyebrow {
    color: var(--rk-theme, var(--brand-accent));
}
.modal-subtitle {
    margin-top: 5px;
    color: var(--text-primary);
    font-family: 'Poppins', sans-serif;
    font-size: 16px;
    font-weight: 900;
}
.modal-stats-grid {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 11px;
}
.modal-stat-box {
    min-width: 0;
    min-height: 94px;
    padding: 14px 10px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    border-radius: 14px;
    background: var(--bg-deep);
    border: 1px solid var(--border-color);
    text-align: center;
}
.m-val {
    color: var(--text-primary);
    font-family: 'Poppins', sans-serif;
    font-size: 22px;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
}
.m-lbl {
    color: var(--text-muted);
    font-size: 8px;
    font-weight: 900;
    letter-spacing: .08em;
}
.theme-gol .m-val,
.theme-asi .m-val { color: var(--bar-green); }
.theme-tir .m-val,
.theme-pue .m-val { color: #3b82f6; }
.theme-tck .m-val { color: var(--gold-accent); }
.theme-tar .m-val { color: var(--bar-red); }
.theme-atj .m-val { color: #0ea5e9; }

@media (max-width: 1220px) {
    .rk-pro-header {
        grid-template-columns: 1fr;
    }
    .rk-pro-primary-controls {
        grid-template-columns: minmax(210px, 1.1fr) minmax(190px, .9fr) auto;
    }
    .rk-pro-filterbar {
        grid-template-columns: repeat(3, minmax(0, 1fr)) minmax(150px, 1fr) minmax(200px, 1fr) 44px;
    }
    .player-profile-data-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (max-width: 840px) {
    #pjHeroContainer.player-profile-pro {
        grid-template-columns: 155px minmax(0, 1fr);
        gap: 20px;
        padding: 21px;
    }
    .player-profile-pro__visual {
        padding-right: 18px;
    }
    .player-avatar-pro {
