    }
    .rk-team-logo {
        display: none;
    }
    .rk-table th:nth-child(1), .rk-table td:nth-child(1) { width: 9%; }
    .rk-table th:nth-child(2), .rk-table td:nth-child(2) { width: 49%; }
    .rk-table th:nth-child(3), .rk-table td:nth-child(3) { width: 12%; }
    .rk-table th:nth-child(5), .rk-table td:nth-child(5) { width: 15%; }
    .rk-table th:nth-child(6), .rk-table td:nth-child(6) { width: 15%; }
}

/* ==========================================================================
   COMPONENTES AUXILIARES, ACCESIBILIDAD Y ADAPTACIÓN GENERAL
   ========================================================================== */

:root {
    --sidebar-width: 300px;
    --content-max-width: 1920px;
    --control-height: 44px;
    --radius-xs: 0.375rem;
    --radius-sm: 0.5rem;
    --radius-md: 0.75rem;
    --radius-lg: 1rem;
    --radius-xl: 1.25rem;
    --shadow-soft: 0 4px 16px rgba(15, 23, 42, 0.08);
    --shadow-panel: 0 10px 30px rgba(15, 23, 42, 0.10);
    --focus-ring: 0 0 0 3px color-mix(in srgb, var(--brand-accent) 28%, transparent);
    --safe-top: env(safe-area-inset-top, 0px);
    --safe-right: env(safe-area-inset-right, 0px);
    --safe-bottom: env(safe-area-inset-bottom, 0px);
    --safe-left: env(safe-area-inset-left, 0px);
}

html {
    min-width: 320px;
    min-height: 100%;
    background: var(--bg-deep);
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
}

body {
    min-width: 320px;
    min-height: 100vh;
    min-height: 100dvh;
    isolation: isolate;
}

button,
input,
select,
textarea {
    font: inherit;
}

button,
[role="button"],
.menu-option,
.custom-display,
.custom-item,
.pj-stat-card {
    -webkit-tap-highlight-color: transparent;
}

button:disabled,
input:disabled,
select:disabled,
[aria-disabled="true"] {
    cursor: not-allowed;
    opacity: 0.55;
    filter: grayscale(0.2);
}

img {
    max-width: 100%;
}

::selection {
    background: color-mix(in srgb, var(--brand-accent) 28%, transparent);
    color: var(--text-primary);
}

/* Accesibilidad incorporada en el index actualizado */
.skip-link {
    position: fixed;
    top: max(10px, var(--safe-top));
    left: max(10px, var(--safe-left));
    z-index: 1000000;
    padding: 11px 16px;
    border: 2px solid var(--brand-accent);
    border-radius: var(--radius-sm);
    background: var(--bg-panel);
    color: var(--text-primary);
    box-shadow: var(--shadow-panel);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.05em;
    text-decoration: none;
    transform: translateY(calc(-100% - 30px));
    transition: transform 0.2s ease;
}

.skip-link:focus,
.skip-link:focus-visible {
    transform: translateY(0);
    outline: none;
}

.visually-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

.no-script-warning {
    position: fixed;
    inset: 0;
    z-index: 1000001;
    display: grid;
    place-items: center;
    padding: 30px;
    background: var(--bg-deep);
    color: var(--text-primary);
    font-size: clamp(14px, 2vw, 20px);
    font-weight: 900;
    line-height: 1.6;
    text-align: center;
}

:where(
    button,
    input,
    select,
    textarea,
    a,
    [role="button"],
    .custom-display,
    .custom-item,
    .menu-option,
    .pj-stat-card
):focus-visible {
    outline: 2px solid var(--brand-accent);
    outline-offset: 3px;
    box-shadow: var(--focus-ring);
}

/* Relación directa con el layout principal del index */
.app-container {
    min-height: 100vh;
    min-height: 100dvh;
}

.main-content {
    width: calc(100% - var(--sidebar-width));
    margin-left: var(--sidebar-width);
    padding-right: max(20px, var(--safe-right));
    padding-bottom: max(50px, calc(30px + var(--safe-bottom)));
}

.sidebar {
    width: var(--sidebar-width);
    padding-left: var(--safe-left);
}

.top-bar-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 15px;
    min-width: 0;
}

.focus-group {
    flex-grow: 1.25;
}

.menu-accordion,
.source-block {
    min-width: 0;
}


.editor-panel-style:hover {
    border-color: color-mix(in srgb, var(--brand-accent) 32%, var(--border-color));
}

/* Selectores nativos antes de que escaner.js los convierta en custom selects */
.modern-input {
    width: 100%;
    min-width: 0;
    min-height: var(--control-height);
    padding: 10px 42px 10px 15px;
    border: 0;
    border-radius: inherit;
    outline: none;
    background: transparent;
    color: var(--text-primary);
    font-family: 'Montserrat', sans-serif;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.035em;
    cursor: pointer;
    appearance: none;
    -webkit-appearance: none;
}

.modern-input.numeric-input {
    color: var(--brand-accent);
    font-family: 'Poppins', sans-serif;
    font-size: 14px;
    font-weight: 900;
}

.modern-input option,
.modern-input optgroup {
    background: var(--bg-panel);
    color: var(--text-primary);
    font-weight: 700;
}

.custom-select-wrapper {
    min-width: 0;
    min-height: var(--control-height);
}

.custom-select-wrapper:focus-within {
    border-color: var(--brand-accent);
    box-shadow: var(--focus-ring);
}

.custom-select-wrapper:has(> .modern-input:not(.hidden-native-select))::after {
    content: "\f078";
    position: absolute;
    right: 14px;
    top: 50%;
    color: var(--text-muted);
    font-family: "Font Awesome 6 Free";
    font-size: 10px;
    font-weight: 900;
    pointer-events: none;
    transform: translateY(-50%);
}

.custom-select-wrapper.with-team .modern-input {
    padding-left: 10px;
}

.custom-display {
    min-width: 0;
    min-height: calc(var(--control-height) - 2px);
    gap: 12px;
    outline: none;
}

.custom-display span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.custom-list {
    width: max(100%, 230px);
    max-height: min(340px, 55dvh);
    overscroll-behavior: contain;
}

.custom-item,
.menu-option,
.accordion-header,
.category-btn,
.db-market-btn,
.db-split-btn,
.db-pro-btn,
.db-pro-btn-back {
    user-select: none;
}

.img-preview-container {
    flex: 0 0 auto;
    aspect-ratio: 1;
    object-fit: contain;
}

.input-logo[src=""],
.team-logo[src=""],
.modal-team-logo[src=""] {
    visibility: hidden;
}

/* Acordeón y menú lateral */
.accordion-header .arrow {
    flex: 0 0 auto;
    transition: transform 0.25s ease, color 0.25s ease;
}

.accordion-header.active .arrow {
    color: var(--brand-accent);
    transform: rotate(180deg);
}

.sidebar-scroll-area {
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
}

.menu-option {
    position: relative;
}

.menu-option.active::after {
    content: "";
    position: absolute;
    top: 50%;
    right: 12px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    transform: translateY(-50%);
}

/* HUD y tendencias */
.text-gradient {
    background: linear-gradient(110deg, var(--brand-accent), var(--gold-accent));
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent;
    -webkit-text-fill-color: transparent;
}

.trend-container {
    min-height: 22px;
    flex-wrap: wrap;
}

.trend-hit,
.trend-miss {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    font-size: 12px;
    line-height: 1;
}

.trend-hit {
    background: color-mix(in srgb, var(--bar-green) 14%, transparent);
}

.trend-miss {
    background: color-mix(in srgb, var(--bar-red) 12%, transparent);
}

.highlight {
    position: relative;
    color: var(--brand-accent) !important;
}

.highlight::after {
    content: "";
    position: absolute;
    left: 18%;
    right: 18%;
    bottom: 7px;
    height: 2px;
    border-radius: 999px;
    background: var(--brand-accent);
    opacity: 0.7;
}

/* Tablas: relación con todas las vistas del index y filas creadas por JS */
.table-wrapper {
    min-width: 0;
    overflow: hidden;
}

.table-container,
.db-table-container-wrap,
.ac-table-wrapper,
.table-maestra-container:not(.rk-main-card) {
    max-width: 100%;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-gutter: stable;
    -webkit-overflow-scrolling: touch;
}

.data-table,
.ac-table,
.tm-table,
.player-log-table,
.league-matrix-table {
    font-variant-numeric: tabular-nums;
}

.data-table th,
.ac-table th,
.tm-table th,
.player-log-table th {
    white-space: nowrap;
}

.data-table tbody tr,
.ac-table tbody tr,
.tm-table tbody tr,
.player-log-table tbody tr {
    transition: background-color 0.18s ease, transform 0.18s ease;
}

.data-table tbody tr:focus-within td,
.ac-table tbody tr:focus-within td,
.tm-table tbody tr:focus-within td,
.player-log-table tbody tr:focus-within td {
    background: color-mix(in srgb, var(--brand-accent) 9%, var(--bg-panel));
}

.league-matrix-table {
    min-width: 760px;
    table-layout: fixed;
}

.league-matrix-table th:first-child,
.league-matrix-table td:first-child {
    position: sticky;
    left: 0;
    z-index: 3;
    background: var(--bg-panel);
    box-shadow: 5px 0 10px rgba(15, 23, 42, 0.06);
}

.league-matrix-table thead th:first-child {
    z-index: 4;
    background: var(--bg-deep);
}

.matrix-self {
    background: color-mix(in srgb, var(--brand-accent) 15%, var(--bg-panel)) !important;
    box-shadow: inset 0 0 0 1px var(--brand-accent);
}

/* Columnas dinámicas del historial de jugadores */
:where(
    .col-goles,
    .col-asistencias,
    .col-tiros,
    .col-tiros-arco,
    .col-pases,
    .col-tackles,
    .col-faltas-c,
    .col-faltas-r,
    .col-atajadas,
    .col-amarillas,
    .col-rojas,
    .col-offsides,
    .col-head-prom,
    .col-head-total
) {
    min-width: 72px;
    text-align: center;
    font-family: 'Poppins', sans-serif;
    font-variant-numeric: tabular-nums;
}

.col-rival {
    min-width: 175px;
    text-align: left !important;
}

.col-goles,
.col-asistencias,
.col-tiros-arco,
.col-atajadas {
    background: color-mix(in srgb, var(--brand-accent) 5%, transparent);
}

.col-tackles,
.col-amarillas {
    background: color-mix(in srgb, var(--bar-yellow) 5%, transparent);
}

.col-faltas-c,
.col-rojas {
    background: color-mix(in srgb, var(--bar-red) 4%, transparent);
}

.odds-line-wrapper {
    min-width: 145px;
}

/* Mejor adaptación a tablets */
@media (max-width: 1100px) {
    .main-content {
        width: 100%;
        margin-left: 0;
        padding-right: max(16px, var(--safe-right));
        padding-left: max(16px, var(--safe-left));
    }

    .sidebar {
        width: min(var(--sidebar-width), 88vw);
        padding-top: var(--safe-top);
    }


    .top-bar-actions {
        width: 100%;
        margin-left: 0 !important;
        justify-content: flex-start;
        flex-wrap: wrap;
    }

    .top-bar-actions .db-pro-btn,
    .top-bar-actions .db-pro-btn-back {
        width: auto;
        max-width: 100%;
    }

}

@media (max-width: 820px) {
    .main-content {
        gap: 14px;
        padding-top: 14px;
    }

    .top-bar,
    .summary-hud,
    .player-control-panel,
    .db-hero {
        padding: 16px;
        border-radius: var(--radius-md);
    }

    .hud-title {
        font-size: clamp(19px, 5vw, 24px);
    }

    .player-filters-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        width: 100%;
    }

    .pro-search-box {
        grid-column: 1 / -1;
    }

    .filter-group-pj {
        min-width: 0;
    }

    .player-stats-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

}

@media (max-width: 600px) {
    :root {
        --control-height: 46px;
    }

    .main-content {
        padding: 10px max(10px, var(--safe-right)) max(28px, var(--safe-bottom)) max(10px, var(--safe-left));
    }

    .top-bar,
    .summary-hud,
    .player-control-panel,
    .db-hero {
        padding: 14px;
    }

    .top-bar-actions {
        gap: 10px;
    }

    .top-bar-actions .db-pro-btn,
    .top-bar-actions .db-pro-btn-back {
        flex: 1 1 150px;
        justify-content: center;
    }

    .player-filters-row {
        grid-template-columns: 1fr;
    }

    .pro-search-box {
        grid-column: auto;
    }

    .player-categories {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .category-btn {
        width: 100%;
        min-height: 42px;
        padding: 8px 12px;
    }

    .player-stats-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
    }

    .pj-stat-card {
        min-height: 112px;
    }

    .pj-stat-avg {
        font-size: 25px;
    }

    .odds-bar-results,
    .odds-bar-section {
        min-width: 0;
        width: 100%;
    }

    .data-table {
        min-width: 520px;
    }

}

@media (max-width: 420px) {
    .brand-header {
        padding-top: 56px;
    }

    .player-categories,
    .player-stats-grid {
        grid-template-columns: 1fr;
    }

    .pj-stat-card {
        min-height: 104px;
    }

    .hud-stats {
        padding: 13px;
    }

    .stat-text-row,
    .mini-bar-header {
        font-size: 14px;
    }

    .custom-list {
        width: min(92vw, 340px);
    }

}

/* Dispositivos táctiles: objetivos cómodos sin alterar escritorio */
@media (pointer: coarse) {
    .theme-toggle-btn,
    .mobile-menu-btn,
    .mobile-close-btn,
    .pro-modal-close {
        min-width: 44px;
        min-height: 44px;
    }

    .menu-option,
    .custom-item,
    .accordion-header,
    .db-market-btn,
    .db-split-btn {
        min-height: 42px;
    }
}

/* Respeta la preferencia del sistema y evita parpadeos/mareo */
@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* Alto contraste del sistema operativo */
@media (forced-colors: active) {
    .status-dot,
    .bar,
    .mini-double-bar,
    .odds-progress-container,
    .leg-box {
        forced-color-adjust: none;
    }

    button,
    input,
    select,
    .custom-select-wrapper,
    .editor-panel-style {
        border: 1px solid CanvasText;
    }
}

/* Respaldo para navegadores sin color-mix */
@supports not (color: color-mix(in srgb, black, white)) {
    :where(
        button,
        input,
        select,
        textarea,
        a,
        [role="button"],
        .custom-display,
        .custom-item,
        .menu-option,
        .pj-stat-card
    ):focus-visible {
        box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.25);
    }

    .editor-panel-style:hover {
        border-color: var(--brand-accent);
    }

    .trend-hit {
        background: rgba(16, 185, 129, 0.14);
    }

    .trend-miss {
        background: rgba(239, 68, 68, 0.12);
    }

    .matrix-self {
        background: rgba(16, 185, 129, 0.12) !important;
    }
}

/* ==========================================================================
   ARREGLO DE SCROLL BARS VISIBLES (VIP / MODAL / TABLAS)
   ========================================================================== */

/* 1. Scroll global más grueso y contrastante */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: var(--bg-deep); border-left: 1px solid var(--border-color); }
::-webkit-scrollbar-thumb { background: var(--text-muted); border-radius: 10px; border: 2px solid var(--bg-deep); transition: 0.3s;}
::-webkit-scrollbar-thumb:hover { background: var(--brand-accent); }

/* 2. Scroll visible en la lista de búsqueda de Player Props */
.pro-search-results::-webkit-scrollbar { width: 8px; }
.pro-search-results::-webkit-scrollbar-thumb { background: var(--brand-accent); border-radius: 8px; border: none; }
.pro-search-results::-webkit-scrollbar-track { background: var(--bg-deep); border: none; }

/* 3. Scroll visible dentro del Modal VIP */
.pro-modal-content--player::-webkit-scrollbar { width: 8px; }
.pro-modal-content--player::-webkit-scrollbar-thumb { background: var(--brand-accent); border-radius: 8px; border: none; }
.pro-modal-content--player::-webkit-scrollbar-track { background: var(--bg-panel); border-radius: 0 24px 24px 0; border: none; }

/* 4. Arreglo para permitir el movimiento lateral en tablas de rankings */
.rk-table-scroll {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
}
/* FIX LEADERBOARD MOSTRAR: evita click-through hacia las filas */
.rk-custom-wrapper,
.rk-custom-wrapper .custom-display,
.rk-custom-wrapper .custom-list,
.rk-custom-wrapper .custom-item {
    pointer-events: auto;
}
.rk-custom-wrapper.focused {
    z-index: 200000 !important;
}
.rk-filter-limit {
    position: relative;
    z-index: 200001;
}

/* FIX V4 LEADERBOARD: scroll vertical propio y cabecera fija */
#vista-rankings .rk-table-scroll {
    max-height: min(520px, calc(100dvh - 500px));
    min-height: 260px;
    overflow-x: auto;
    overflow-y: auto;
    scrollbar-gutter: stable;
    overscroll-behavior: contain;
}

#vista-rankings .rk-table thead th {
    position: sticky;
    top: 0;
    z-index: 5;
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar {
    width: 10px;
    height: 8px;
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar-thumb {
    background: var(--rk-theme);
    border-radius: 10px;
    border: 2px solid var(--bg-panel);
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar-track {
    background: var(--bg-deep);
}

@media (max-height: 760px) {
    #vista-rankings .rk-table-scroll {
        max-height: 360px;
        min-height: 220px;
    }
}


/* ==========================================================================
   FIX V6 LEADERBOARD — lista completa, sin scroll vertical anidado
   ========================================================================== */

/*
   La tabla ya no crea un segundo scroll vertical. Se expande con todas las
   filas y utiliza únicamente el scroll principal de la aplicación.
*/
#vista-rankings {
    flex: 0 0 auto;
    min-height: min-content;
}

#vista-rankings .rk-main-card {
    overflow: hidden;
}

#vista-rankings .rk-table-scroll {
    width: 100%;
    max-width: 100%;
    max-height: none !important;
    min-height: 0 !important;
    height: auto !important;
    overflow-x: auto !important;
    overflow-y: visible !important;
    scrollbar-gutter: auto !important;
    overscroll-behavior: auto;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--rk-theme) 70%, #64748b) transparent;
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar {
    width: 0;
    height: 7px;
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar-track {
    background: transparent;
}

#vista-rankings .rk-table-scroll::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: color-mix(in srgb, var(--rk-theme) 70%, #64748b);
}

/* Sin cabecera sticky dentro de un scroll anidado. */
#vista-rankings .rk-table thead th {
    position: static !important;
    top: auto !important;
}

#vista-rankings .rk-player-row:last-child td {
    border-bottom: 0;
}

/* V10 — rendimiento de Leaderboard y carga progresiva de rostros */
#vista-rankings .rk-table-scroll {
    contain: layout paint;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
}
#vista-rankings .rk-player-row {
    content-visibility: auto;
    contain-intrinsic-size: 76px;
}
#vista-rankings .rk-avatar {
    overflow: hidden;
    background: linear-gradient(110deg, #eef2f7 8%, #f8fafc 18%, #eef2f7 33%);
    background-size: 200% 100%;
}
#vista-rankings .rk-avatar-img.is-loading {
    animation: incaFaceSkeleton 1.15s linear infinite;
}
@keyframes incaFaceSkeleton {
    to { transform: translateZ(0); }
}
#vista-rankings select,
#vista-rankings .custom-select-wrapper,
#vista-rankings .custom-display {
    touch-action: manipulation;
}


/* INCA STATS V12 — rendimiento visual */
#tablaBodyRankings tr {
    content-visibility: auto;
    contain-intrinsic-size: 72px;
    contain: layout paint style;
}
.rk-player-avatar,
.player-profile-photo,
#modalFotoPj {
    transform: translateZ(0);
    backface-visibility: hidden;
}
#tablaBodyRankings img {
    transition: opacity .16s ease;
}
.rk-table-scroll {
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
}
@media (prefers-reduced-motion: reduce) {
    #tablaBodyRankings img,
    .rk-player-avatar {
        transition: none !important;
    }
}


/* INCA STATS V13 — scroll único, fluidez y estabilidad */
@media (min-width: 1101px) {
    html, body { height: 100%; overflow: hidden !important; }
    .main-content {
        overflow-y: auto !important;
        overflow-x: hidden !important;
        overscroll-behavior-y: none;
        scroll-behavior: auto;
        scrollbar-gutter: stable;
        will-change: scroll-position;
    }
    #vista-rankings .rk-table-scroll {
        overflow-x: auto !important;
        overflow-y: visible !important;
        overscroll-behavior: auto !important;
        contain: none !important;
    }
}

#tablaBodyRankings tr {
    content-visibility: auto;
    contain-intrinsic-block-size: 76px;
    contain: layout paint;
}

#vista-rankings .rk-main-card,
#vista-rankings .rk-table,
#vista-rankings .rk-table-scroll {
    transform: translateZ(0);
}

.rk-avatar-img,
.rk-team-logo {
    content-visibility: auto;
}

/* Evita animaciones costosas durante scroll rápido. */
.main-content.is-scrolling #tablaBodyRankings img,
.main-content.is-scrolling .rk-player-row {
    transition: none !important;
}


/* =========================================================
   INCA STATS VISUAL PRO V15 — HOME/AWAY COMPACT REPORT
   ========================================================= */

.summary-hud {
    grid-template-columns: minmax(280px, 1fr) minmax(360px, auto);
    grid-template-areas:
        "info filters";
    padding: 18px 20px;
    gap: 14px 20px;
}

.inca-visual-heading {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.inca-visual-heading-copy {
    min-width: 0;
}

.inca-visual-main-logo {
    width: 58px;
    height: 58px;
    flex: 0 0 58px;
    object-fit: contain;
    padding: 6px;
    background: var(--bg-deep);
    border: 1px solid var(--border-color);
    border-radius: 15px;
    filter: drop-shadow(0 5px 8px rgba(15, 23, 42, .18));
}

.stat-text-row,
.hit-bar,
.miss-bar,
.stat-fraction,
.split-tables-container {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
    align-items: start;
}

.table-wrapper {
    min-width: 0;
    overflow: hidden;
    border-radius: 12px;
}

.table-header-title {
    min-height: 58px;
    padding: 10px 13px;
    justify-content: space-between;
    gap: 10px;
    border-radius: 12px 12px 0 0;
}

.inca-panel-title-copy {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.inca-panel-title-copy > div {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.inca-panel-title-copy strong {
    color: var(--text-primary);
    font: 900 11px/1.2 'Poppins', sans-serif;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.inca-panel-title-copy span {
    color: var(--text-muted);
    font: 700 9px/1.2 'Montserrat', sans-serif;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: 0;
    text-transform: none;
}

.inca-panel-count {
    min-width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: var(--bg-panel);
    border: 1px solid var(--border-color);
    color: var(--brand-accent);
    font: 900 11px/1 'Montserrat', sans-serif;
}

.table-container {
    width: 100%;
    overflow-x: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
}

.data-table {
    width: 100%;
    min-width: 570px;
    table-layout: fixed;
}

.data-table .col-date {
    width: 92px;
}

.data-table .col-score {
    width: 112px;
}

.data-table .col-team {
    width: auto;
}

.data-table th {
    padding: 8px 6px;
    font-size: 8.5px;
    text-align: center !important;
}

.data-table td {
    padding: 6px 6px;
    height: 48px;
    font-size: 10px;
}

.inca-visual-match-row {
    animation: incaRowIn .22s ease both;
    animation-delay: var(--row-delay, 0ms);
    content-visibility: auto;
    contain-intrinsic-size: 48px;
}

@keyframes incaRowIn {
    from { opacity: 0; transform: translateY(3px); }
    to { opacity: 1; transform: translateY(0); }
}

.inca-date-cell {
    text-align: center !important;
    white-space: nowrap;
}

.inca-date-main {
    display: block;
    color: var(--text-primary);
    font: 800 9.5px/1.2 'Montserrat', sans-serif;
}

.inca-date-sub {
    display: block;
    margin-top: 3px;
    color: var(--text-muted);
    font: 700 7.5px/1 'Montserrat', sans-serif;
    overflow: hidden;
    text-overflow: ellipsis;
}

.inca-match-team {
    display: flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
}

.inca-match-team--away {
    flex-direction: row-reverse;
    text-align: right;
}

.inca-match-logo {
    width: 24px;
    height: 24px;
    flex: 0 0 24px;
    object-fit: contain;
    filter: drop-shadow(0 2px 3px rgba(15, 23, 42, .14));
}

.inca-match-team span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-primary);
    font: 800 9.5px/1.15 'Montserrat', sans-serif;
}

.inca-team-cell {
    overflow: hidden;
}

.inca-score-cell {
    text-align: center !important;
}

.inca-stat-score {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    min-width: 66px;
    padding: 4px 7px;
    border-radius: 7px;
    background: rgba(255, 255, 255, .64);
    border: 1px solid rgba(148, 163, 184, .32);
    color: #0f172a;
    font: 900 11px/1 'Montserrat', sans-serif;
}

.inca-stat-score b {
    opacity: .55;
}

.inca-total-chip {
    display: block;
    max-width: 105px;
    margin: 3px auto 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-muted);
    font: 800 7px/1.1 'Montserrat', sans-serif;
}

.row-hit td {
    background: rgba(190, 235, 132, .42) !important;
}

.row-miss td {
    background: rgba(231, 164, 164, .42) !important;
}

.row-hit td:first-child,
.row-miss td:first-child {
    border-left-width: 3px;
}

.row-hit .inca-stat-score {
    border-color: rgba(34, 197, 94, .38);
}

.row-miss .inca-stat-score {
    border-color: rgba(239, 68, 68, .34);
}

.inca-empty-row {
    font-size: 10px !important;
}

body.dark-mode .inca-stat-score {
    background: rgba(15, 23, 42, .72);
    color: #f8fafc;
}

body.dark-mode .row-hit td {
    background: rgba(34, 197, 94, .15) !important;
}

body.dark-mode .row-miss td {
    background: rgba(239, 68, 68, .13) !important;
}

@media (max-width: 1180px) {
    .split-tables-container {
        grid-template-columns: 1fr;
    }

    .data-table {
        min-width: 650px;
    }
}

@media (max-width: 900px) {
    .summary-hud {
        grid-template-columns: 1fr;
        grid-template-areas:
            "info"
            "filters";
    }

    .hud-filters {
        width: 100%;
        justify-self: stretch;
    }

    .hud-filters .filter-group {
        min-width: min(100%, 170px);
    }
}

@media (max-width: 640px) {
    .summary-hud {
        padding: 14px;
    }

    .inca-visual-main-logo {
        width: 48px;
        height: 48px;
        flex-basis: 48px;
    }

    .hud-title {
        font-size: 18px;
    }

    .hud-filters {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 8px;
    }

    .hud-filters .filter-group {
        min-width: 0;
    }

    .data-table {
        min-width: 560px;
    }

    .table-container {
        -webkit-overflow-scrolling: touch;
    }
}

@media (prefers-reduced-motion: reduce) {
    .inca-visual-match-row {
        animation: none;
    }
}


