/* =========================================================
   INCA STATS V15.4 — PLAYER VIP / MATCH LOG COMPACTO
   ========================================================= */

/* El contenedor puede usar todo el ancho disponible */
.player-history-card,
.player-match-log,
.vip-history-card,
#playerMatchLog,
#tablaHistorialJugador {
    width: 100%;
    max-width: none;
}

/* Tabla más densa, con prioridad para PARTIDO */
.player-history-table,
.match-log-table,
.vip-match-table,
#tablaHistorialJugador,
#tablaHistorialJugador table {
    width: 100% !important;
    min-width: 1180px !important;
    table-layout: fixed !important;
    border-collapse: collapse;
}

/* Anchos orientados a lectura real */
.player-history-table th:nth-child(1),
.player-history-table td:nth-child(1),
.match-log-table th:nth-child(1),
.match-log-table td:nth-child(1),
#tablaHistorialJugador th:nth-child(1),
#tablaHistorialJugador td:nth-child(1) {
    width: 84px !important;
}

.player-history-table th:nth-child(2),
.player-history-table td:nth-child(2),
.match-log-table th:nth-child(2),
.match-log-table td:nth-child(2),
#tablaHistorialJugador th:nth-child(2),
#tablaHistorialJugador td:nth-child(2) {
    width: 90px !important;
}

.player-history-table th:nth-child(3),
.player-history-table td:nth-child(3),
.match-log-table th:nth-child(3),
.match-log-table td:nth-child(3),
#tablaHistorialJugador th:nth-child(3),
#tablaHistorialJugador td:nth-child(3) {
    width: 210px !important;
}

.player-history-table th:nth-child(4),
.player-history-table td:nth-child(4),
.match-log-table th:nth-child(4),
.match-log-table td:nth-child(4),
#tablaHistorialJugador th:nth-child(4),
#tablaHistorialJugador td:nth-child(4) {
    width: 54px !important;
}

.player-history-table th:nth-child(5),
.player-history-table td:nth-child(5),
.match-log-table th:nth-child(5),
.match-log-table td:nth-child(5),
#tablaHistorialJugador th:nth-child(5),
#tablaHistorialJugador td:nth-child(5) {
    width: 58px !important;
}

/* Todas las métricas numéricas más angostas */
.player-history-table th:nth-child(n+6),
.player-history-table td:nth-child(n+6),
.match-log-table th:nth-child(n+6),
.match-log-table td:nth-child(n+6),
#tablaHistorialJugador th:nth-child(n+6),
#tablaHistorialJugador td:nth-child(n+6) {
    width: 54px !important;
    text-align: center !important;
}

/* Encabezado más pequeño y limpio */
.player-history-table thead th,
.match-log-table thead th,
#tablaHistorialJugador thead th {
    padding: 7px 4px !important;
    font-size: 7.4px !important;
    line-height: 1.05 !important;
    letter-spacing: .01em !important;
    white-space: nowrap !important;
}

/* Filas más compactas */
.player-history-table tbody td,
.match-log-table tbody td,
#tablaHistorialJugador tbody td {
    height: 48px !important;
    padding: 6px 5px !important;
    vertical-align: middle !important;
}

/* Fecha */
.player-history-table tbody td:nth-child(1),
.match-log-table tbody td:nth-child(1),
#tablaHistorialJugador tbody td:nth-child(1) {
    font-size: 10.5px !important;
    line-height: 1.05 !important;
    white-space: nowrap !important;
}

/* Torneo: más chico */
.player-history-table tbody td:nth-child(2),
.match-log-table tbody td:nth-child(2),
#tablaHistorialJugador tbody td:nth-child(2) {
    font-size: 8px !important;
    line-height: 1.08 !important;
    letter-spacing: 0 !important;
    word-break: normal !important;
    overflow-wrap: anywhere !important;
}

/* Partido: más ancho y nombres más legibles */
.player-history-table tbody td:nth-child(3),
.match-log-table tbody td:nth-child(3),
#tablaHistorialJugador tbody td:nth-child(3) {
    font-size: 10.5px !important;
    line-height: 1.08 !important;
    font-weight: 800 !important;
    white-space: normal !important;
    word-break: normal !important;
    overflow-wrap: anywhere !important;
}

/* Condición y minutos */
.player-history-table tbody td:nth-child(4),
.player-history-table tbody td:nth-child(5),
.match-log-table tbody td:nth-child(4),
.match-log-table tbody td:nth-child(5),
#tablaHistorialJugador tbody td:nth-child(4),
#tablaHistorialJugador tbody td:nth-child(5) {
    font-size: 9.5px !important;
    line-height: 1 !important;
}

/* Mercados/estadísticas numéricas más pequeños */
.player-history-table tbody td:nth-child(n+6),
.match-log-table tbody td:nth-child(n+6),
#tablaHistorialJugador tbody td:nth-child(n+6) {
    font-size: 9.5px !important;
    line-height: 1 !important;
    font-weight: 800 !important;
}

/* Cabecera general del historial más compacta */
.player-history-card .card-header,
.player-match-log .card-header,
.vip-history-card .card-header,
#playerMatchLog .card-header {
    min-height: 50px !important;
    padding: 10px 14px !important;
}

.player-history-card .card-header h3,
.player-match-log .card-header h3,
.vip-history-card .card-header h3,
#playerMatchLog .card-header h3 {
    font-size: 13px !important;
    line-height: 1.1 !important;
}

/* El contenedor conserva scroll horizontal solo si la pantalla realmente no alcanza */
.player-history-table-wrap,
.match-log-scroll,
.vip-history-scroll,
#tablaHistorialJugador {
    overflow-x: auto !important;
    overflow-y: visible !important;
    scrollbar-width: thin;
    overscroll-behavior: contain;
}

@media (min-width: 1280px) {
    .player-history-table,
    .match-log-table,
    .vip-match-table,
    #tablaHistorialJugador,
    #tablaHistorialJugador table {
        min-width: 1080px !important;
    }

    .player-history-table th:nth-child(3),
    .player-history-table td:nth-child(3),
    .match-log-table th:nth-child(3),
    .match-log-table td:nth-child(3),
    #tablaHistorialJugador th:nth-child(3),
    #tablaHistorialJugador td:nth-child(3) {
        width: 230px !important;
    }
}

@media (max-width: 900px) {
    .player-history-table,
    .match-log-table,
    .vip-match-table,
    #tablaHistorialJugador,
    #tablaHistorialJugador table {
        min-width: 1080px !important;
    }

    .player-history-table tbody td:nth-child(2),
    .match-log-table tbody td:nth-child(2),
    #tablaHistorialJugador tbody td:nth-child(2) {
        font-size: 7.5px !important;
    }

    .player-history-table tbody td:nth-child(3),
    .match-log-table tbody td:nth-child(3),
    #tablaHistorialJugador tbody td:nth-child(3) {
        font-size: 9.5px !important;
    }
}


/* =========================================================
   INCA STATS V15.5 — PLAYER VIP REFACTORIZADO
   ========================================================= */

/* KPIs: se eliminan los mosaicos fotográficos gigantes */
#vista-jugadores .player-stats-grid {
    display: grid !important;
    grid-template-columns: repeat(6, minmax(118px, 1fr)) !important;
    gap: 9px !important;
    margin: 10px 0 16px !important;
    align-items: stretch;
}

#vista-jugadores .pj-stat-card.pj-kpi-card {
    position: relative;
    min-height: 74px !important;
    height: auto !important;
    padding: 11px 12px !important;
    border-radius: 12px !important;
    overflow: hidden;
    background:
        linear-gradient(135deg, color-mix(in srgb, var(--pj-kpi-accent) 10%, transparent), transparent 62%),
        var(--bg-panel) !important;
    background-image: none !important;
    border: 1px solid var(--border-color) !important;
    box-shadow: 0 5px 14px rgba(15, 23, 42, .07) !important;
    transform: none !important;
}

#vista-jugadores .pj-stat-card.pj-kpi-card::after {
    content: "";
    position: absolute;
    inset: auto 0 0;
    height: 3px;
    background: var(--pj-kpi-accent);
    opacity: .9;
}

#vista-jugadores .pj-stat-card.pj-kpi-card:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 8px 18px rgba(15, 23, 42, .10) !important;
}

#vista-jugadores .pj-stat-overlay,
#vista-jugadores .pj-stat-content {
    display: contents;
}

#vista-jugadores .pj-kpi-topline {
    display: flex;
    align-items: center;
    gap: 7px;
    min-width: 0;
}

#vista-jugadores .pj-kpi-dot {
    width: 7px;
    height: 7px;
    flex: 0 0 7px;
    border-radius: 50%;
    background: var(--pj-kpi-accent);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--pj-kpi-accent) 14%, transparent);
}

#vista-jugadores .pj-stat-title {
    margin: 0 !important;
    color: var(--text-muted) !important;
    text-shadow: none !important;
    font: 900 9px/1.1 'Montserrat', sans-serif !important;
    letter-spacing: .04em !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

#vista-jugadores .pj-kpi-value-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
    margin-top: 9px;
}

#vista-jugadores .pj-stat-avg {
    margin: 0 !important;
    color: var(--text-primary) !important;
    text-shadow: none !important;
    font: 900 24px/.95 'Poppins', sans-serif !important;
    letter-spacing: -.04em;
}

#vista-jugadores .pj-stat-label {
    color: var(--pj-kpi-accent) !important;
    text-shadow: none !important;
    font: 900 8px/1 'Montserrat', sans-serif !important;
    letter-spacing: .04em;
}

/* Match log */
#vista-jugadores .table-maestra-container {
    margin-top: 4px !important;
    border-radius: 14px !important;
    overflow: hidden !important;
