/* =========================================================
   INCA STATS V15.8 — SPLASH PREMIUM
   ========================================================= */

html.inca-boot-active,
html.inca-boot-active body {
    overflow: hidden !important;
}

.inca-boot-splash {
    position: fixed;
    inset: 0;
    z-index: 999999;
    display: grid;
    place-items: center;
    padding: 24px;
    opacity: 1;
    transition: opacity .48s ease, visibility .48s ease;
}

.inca-boot-splash.is-leaving {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

.inca-boot-backdrop {
    position: absolute;
    inset: 0;
    background:
        radial-gradient(circle at 50% 38%, rgba(16,185,129,.18), transparent 32%),
        linear-gradient(145deg, rgba(2,8,23,.96), rgba(7,23,38,.985));
    backdrop-filter: blur(18px);
}

.inca-boot-backdrop::before {
    content: "";
    position: absolute;
    inset: 0;
    opacity: .22;
    background-image:
        linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
    background-size: 34px 34px;
    mask-image: radial-gradient(circle, #000 12%, transparent 76%);
}

.inca-boot-card {
    position: relative;
    z-index: 1;
    width: min(520px, 94vw);
    padding: 34px 34px 28px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,.12);
    border-radius: 28px;
    background: linear-gradient(155deg, rgba(15,35,55,.88), rgba(6,18,32,.94));
    box-shadow:
        0 30px 80px rgba(0,0,0,.45),
        inset 0 1px 0 rgba(255,255,255,.09);
    text-align: center;
}

.inca-boot-card::after {
    content: "";
    position: absolute;
    inset: auto 12% 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, #10b981, transparent);
    filter: blur(.2px);
}

.inca-boot-logo-wrap {
    position: relative;
    width: 116px;
    height: 116px;
    margin: 0 auto 16px;
    display: grid;
    place-items: center;
}

.inca-boot-logo {
    width: 78px;
    height: 78px;
    object-fit: contain;
    z-index: 2;
    filter: drop-shadow(0 8px 18px rgba(0,0,0,.38));
    animation: incaLogoFloat 2.4s ease-in-out infinite;
}

.inca-boot-orbit {
    position: absolute;
    inset: 8px;
    border: 2px solid rgba(16,185,129,.45);
    border-top-color: #34d399;
    border-radius: 50%;
    animation: incaOrbit 2s linear infinite;
}

.inca-boot-orbit--two {
    inset: 20px;
    border-color: rgba(255,255,255,.12);
    border-right-color: #22c55e;
    animation-direction: reverse;
    animation-duration: 1.35s;
}

.inca-boot-brand {
    color: #f8fafc;
    font: 900 18px/1 'Poppins', sans-serif;
    letter-spacing: -.02em;
}

.inca-boot-brand span {
    color: #34d399;
}

.inca-boot-title {
    margin-top: 10px;
    color: #f8fafc;
    font: 900 28px/1.05 'Poppins', sans-serif;
    letter-spacing: -.04em;
}

.inca-boot-subtitle {
    min-height: 20px;
    margin-top: 10px;
    color: #94a3b8;
    font: 700 11px/1.4 'Montserrat', sans-serif;
}

.inca-boot-progress {
    height: 11px;
    margin-top: 24px;
    padding: 2px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,.10);
    border-radius: 999px;
    background: rgba(255,255,255,.055);
}

.inca-boot-progress-fill {
    width: 0%;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, #10b981, #34d399, #22c55e);
    box-shadow: 0 0 18px rgba(16,185,129,.65);
    transition: width .32s ease;
}

.inca-boot-meta {
    margin-top: 8px;
    display: flex;
    justify-content: space-between;
    color: #cbd5e1;
    font: 800 9px/1 'Montserrat', sans-serif;
