.inca-boot-pills {
    margin-top: 20px;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 7px;
}

.inca-boot-pills span {
    padding: 6px 9px;
    border: 1px solid rgba(148,163,184,.18);
