/* ======================================================================
   CONSOLIDADO DESDE: pro-portal.css
   ====================================================================== */
:root{
  --p-bg:#f6f8fb;--p-surface:#fff;--p-card:#fff;--p-border:#dce4ec;
  --p-text:#102033;--p-muted:#66788c;--p-green:#0bbf8a;--p-green-dark:#07956c;
  --p-soft:#eefbf7;--p-navy:#0e2135;--p-shadow:0 14px 40px rgba(20,45,72,.09)
}
html,body{width:100%;max-width:none;background:var(--p-bg)!important}
body{display:block!important;overflow:hidden!important;text-transform:none!important}
.portal-hidden{display:none!important}
.portal-shell{width:100vw;min-width:100%;height:100vh;overflow-y:auto;overflow-x:hidden;background:var(--p-bg);color:var(--p-text);font-family:Montserrat,Arial,sans-serif;scrollbar-width:thin;scrollbar-color:var(--p-green) #e8edf2}
.portal-shell *{text-transform:none}
.portal-shell::-webkit-scrollbar{width:12px}
.portal-shell::-webkit-scrollbar-track{background:#e8edf2;border:0}
.portal-shell::-webkit-scrollbar-thumb{background:linear-gradient(180deg,var(--p-green),var(--p-green-dark));border:3px solid #e8edf2;border-radius:999px}
.portal-scroll-progress{position:fixed;left:0;top:0;height:3px;width:0;background:linear-gradient(90deg,var(--p-green),#35d6aa);z-index:5000;box-shadow:0 0 12px rgba(11,191,138,.5)}
.portal-topbar{height:76px;position:sticky;top:0;z-index:1000;display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100vw - 1480px)/2));background:rgba(255,255,255,.96);backdrop-filter:blur(18px);border-bottom:1px solid var(--p-border);box-shadow:0 8px 25px rgba(30,55,80,.05)}
.portal-brand{display:flex;align-items:center;gap:12px;background:none;border:0;color:var(--p-navy);font-weight:900;font-size:18px;cursor:pointer}.portal-brand img{width:44px;height:44px;border-radius:50%;box-shadow:0 5px 15px rgba(0,0,0,.12)}.portal-brand b{color:var(--p-green)}
.portal-nav{display:flex;gap:6px}.portal-nav-btn{border:0;background:transparent;color:#627489;padding:11px 13px;border-radius:10px;font-weight:800;cursor:pointer;transition:.2s}.portal-nav-btn:hover,.portal-nav-btn.active{background:var(--p-soft);color:var(--p-green-dark)}.portal-nav-btn.portal-primary{background:var(--p-green);color:#fff;box-shadow:0 8px 20px rgba(11,191,138,.22)}.portal-mobile-menu{display:none}
.portal-page{width:min(1480px,100%);margin:0 auto;padding:42px 32px 86px}
.portal-hero{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:26px;align-items:stretch;padding:50px;border:1px solid var(--p-border);border-radius:26px;background:radial-gradient(circle at 0 0,rgba(11,191,138,.13),transparent 36%),#fff;box-shadow:var(--p-shadow)}
