.league-hub{max-width:1380px;margin:0 auto;padding:34px 28px 70px}
.league-hub-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:20px}
.league-hub-eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#078463;font-weight:800}
.league-hub-head h1{margin:7px 0 6px;font-size:40px;letter-spacing:-.04em;line-height:1;font-weight:760}
.league-hub-head p{margin:0;color:#6a7783;max-width:760px}
.league-hub-selector{display:flex;align-items:center;gap:10px;min-width:340px}
.league-hub-selector label{font-size:10px;text-transform:uppercase;font-weight:800;color:#67737e;letter-spacing:.07em}
.league-hub-select{width:100%;padding:11px 12px;font-weight:700}
.league-hub-tabs{display:flex;gap:4px;overflow:auto;padding:4px;background:#eef2f3;border:1px solid #e1e6e9;border-radius:9px;margin-bottom:16px}
.league-hub-tab{white-space:nowrap;border:0;background:transparent;padding:10px 13px;border-radius:6px;font-weight:700;color:#65717c;cursor:pointer}
.league-hub-tab.active{background:#fff;color:#172433;box-shadow:0 1px 3px rgba(25,38,50,.08)}
.league-hub-panel{padding:18px;min-height:330px}
.league-hub-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}
.league-hub-kpi{border:1px solid #e5eaed;border-radius:8px;padding:12px;background:#fafbfb}
.league-hub-kpi small{display:block;color:#7a8690;font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:700}
.league-hub-kpi strong{font-size:20px;margin-top:4px;display:block}
.league-hub-table{width:100%;border-collapse:collapse}
.league-hub-table th,.league-hub-table td{text-align:left;padding:10px 9px;vertical-align:middle}
.league-hub-team{display:flex;align-items:center;gap:9px;font-weight:700}.league-hub-team img{width:28px;height:28px;object-fit:contain}
.league-hub-fixture{display:grid;grid-template-columns:1fr 105px 1fr 180px;align-items:center;gap:10px;padding:10px 6px;border-bottom:1px solid #edf0f2}
.league-hub-fixture .home{text-align:right}.league-hub-fixture .kick{text-align:center;font-weight:800;font-variant-numeric:tabular-nums}.league-hub-fixture .meta{font-size:11px;color:#75818b}
.league-hub-note{padding:14px;border:1px solid #dae3e7;border-left:3px solid #05a579;border-radius:7px;background:#f8fbfa;color:#52616d;line-height:1.55}
.league-hub-empty{display:flex;min-height:250px;align-items:center;justify-content:center;text-align:center;color:#79858f}
.league-hub-action{border:1px solid #cad5da;background:#fff;padding:8px 11px;border-radius:6px;font-weight:700;cursor:pointer}.league-hub-action:hover{border-color:#00a878;color:#087b5d}
