.league-hub-ref{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px;border-bottom:1px solid #edf0f2}.league-hub-ref strong{display:block}.league-hub-ref small{color:#7a8790}
@media(max-width:900px){.league-hub{padding:25px 14px 60px}.league-hub-head{display:block}.league-hub-selector{min-width:0;margin-top:15px}.league-hub-summary{grid-template-columns:repeat(2,1fr)}.league-hub-fixture{grid-template-columns:1fr 70px 1fr}.league-hub-fixture .meta{grid-column:1/-1;text-align:center}.market-coverage-grid{grid-template-columns:1fr}}



