ter;padding:20px;color:#8a9992;font-size:11px}

/* Match Info: tabla Sofa-like + árbitro */
.fx-match-info-stack{gap:16px!important}.fx-match-info-block>header span{font-size:12px!important}.fx-match-info-block>header small{font-size:10px!important}.fx-table-head{display:flex!important;align-items:center!important;justify-content:space-between!important;gap:16px!important;padding:16px 18px!important}.fx-table-head h2{font-size:24px!important}.fx-table-head p{margin:4px 0 0;color:#778a81;font-size:11px}.fx-table-match-ranks{display:flex;gap:8px}.fx-table-match-ranks>span{min-width:130px;padding:9px 11px;border:1px solid #dce5e2;border-radius:10px;background:#fff}.fx-table-match-ranks small{display:block;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#82918b;font-size:9px}.fx-table-match-ranks b{display:block;margin-top:3px;color:#0b7b5d;font-size:16px}.fx-standings th{font-size:10px!important}.fx-standings td{font-size:11px!important;padding:9px 8px!important}.fx-standings tr.selected{background:#ddf7ec!important;box-shadow:inset 4px 0 0 #0bad7d}.fx-standing-team .fx-team-name{font-size:11px!important}.fx-standing-team em{margin-left:auto;padding:3px 6px;border-radius:999px;background:#0d8363;color:#fff;font-size:8px;font-style:normal;font-weight:900}
.fx-referee-card{display:grid;grid-template-columns:58px minmax(0,1fr) auto auto;align-items:center;gap:14px;padding:18px}.fx-referee-avatar{width:58px;height:58px;display:grid;place-items:center;border-radius:14px;background:#e2f7ef;color:#07815f;font-size:20px}.fx-referee-copy span{color:#0a8967;font-size:9px;font-weight:900;letter-spacing:.10em}.fx-referee-copy h3{margin:4px 0 0;color:#142c34;font:900 22px/1.05 "Inter Tight",Inter,sans-serif}.fx-referee-copy p{margin:5px 0 0;color:#7b8c85;font-size:11px}.fx-referee-windows{display:flex;align-items:center;gap:5px}.fx-referee-windows>span{margin-right:4px;color:#87958f;font-size:9px;font-weight:900}.fx-referee-windows b{width:36px;height:32px;display:grid;place-items:center;border:1px solid #dce5e2;border-radius:8px;background:#f8faf9;color:#4b5c55;font-size:11px}.fx-referee-card>button{height:40px;padding:0 13px;border:1px solid #cfe6dd;border-radius:9px;background:#0b8d68;color:#fff;font-size:10px;font-weight:900;cursor:pointer}.fx-referee-card>button:disabled{background:#eef3f1;color:#91a09a;border-color:#e1e7e4;cursor:default}

