/* ===== v60-product-polish.css ===== */
/* INCA STATS PRO V4.27.60 · PRODUCT POLISH
   Producto visual: márgenes consistentes, tarjetas menos rígidas, login unificado
   y Next Match Bridge para el Analizador. */

:root{
  --v60-green:#079d73;
  --v60-green-deep:#08765a;
  --v60-ink:#102c3b;
  --v60-muted:#71827c;
  --v60-line:#e1e9e6;
  --v60-soft:#f5f8f7;
  --v60-mint:#eaf8f3;
  --v60-shadow:0 14px 40px rgba(18,48,58,.07);
}
*,*::before,*::after{box-sizing:border-box}
html,body{max-width:100%;overflow-x:hidden}

/* ====== MARGEN DE PRODUCTO: NADA SE SALE ====== */
.portal-page{
  width:min(1440px,calc(100% - 36px))!important;
  max-width:1440px!important;
  margin-inline:auto!important;
  padding:30px 0 72px!important;
}
.portal-page>*,.league-hub>*,.fx-match-detail>*,.fx-browser>*{min-width:0;max-width:100%}
.league-hub{max-width:none!important;padding:0!important;margin:0!important}
.league-hub-panel{padding:0!important;background:transparent!important;border:0!important;box-shadow:none!important}
.portal-shell,.portal-view{max-width:100%;overflow-x:hidden}
#scannerView,.app-container,.main-content,.results-section,.top-bar{max-width:100%;min-width:0}
.main-content{overflow-x:hidden!important}
.results-section{width:100%!important}

/* ====== CENTRO DE LIGAS: menos rígido, más producto ====== */
.league-hub-head{
  align-items:center!important;
  padding:8px 4px 22px!important;
  margin-bottom:18px!important;
}
.league-hub-brand{border-radius:16px!important;background:#fff!important;border:1px solid var(--v60-line)!important;box-shadow:0 8px 24px rgba(18,48,58,.04)!important}
.league-hub-head h1{letter-spacing:-.045em!important;color:var(--v60-ink)!important}
.league-hub-selector{min-width:min(360px,100%)!important}
.league-hub-select{height:50px!important;border-radius:13px!important;border:1px solid #dce6e2!important;background:#fff!important;padding:0 15px!important;box-shadow:0 5px 18px rgba(18,48,58,.035)!important}
.league-hub-tabs{
  margin:0 0 24px!important;padding:4px!important;border:1px solid var(--v60-line)!important;
  border-radius:15px!important;background:#f3f7f5!important;overflow:auto!important;
}
.league-hub-tabs button{min-height:52px!important;border-radius:11px!important;padding:0 16px!important;border:0!important;transition:.18s ease!important}
.league-hub-tabs button.active{background:#fff!important;border:0!important;color:var(--v60-ink)!important;box-shadow:0 3px 13px rgba(18,48,58,.08)!important}
.league-hub-tabs button.active::after{content:"";display:block;height:3px;border-radius:999px;background:var(--v60-green);margin:7px auto -7px;width:28px}
.league-section-intro{border-radius:18px!important;border:1px solid var(--v60-line)!important;background:linear-gradient(135deg,#fff 0%,#f7fbf9 100%)!important;box-shadow:0 7px 24px rgba(18,48,58,.035)!important;padding:22px 24px!important;margin-bottom:18px!important}
.league-section-intro h2{color:var(--v60-ink)!important;letter-spacing:-.035em!important}
.league-source-badge{border-radius:14px!important;background:#eef8f4!important;border:1px solid #d8eee6!important}

.league-day-wrap{border-radius:18px!important;border:1px solid var(--v60-line)!important;background:#fff!important;box-shadow:0 7px 24px rgba(18,48,58,.035)!important;padding:16px!important;margin-bottom:18px!important}
.league-day-picker{gap:7px!important;flex-wrap:wrap!important}
.league-day-chip{border-radius:12px!important;border:1px solid #e2e9e6!important;background:#f8faf9!important;min-height:48px!important;padding:8px 13px!important;transition:.18s ease!important}
.league-day-chip:hover{border-color:#b9dfd1!important;background:#f1faf6!important;transform:translateY(-1px)}
.league-day-chip.active{background:var(--v60-ink)!important;color:#fff!important;border-color:var(--v60-ink)!important;box-shadow:0 8px 18px rgba(16,44,59,.16)!important}

.league-fixture-day{margin:0 0 26px!important}
.league-fixture-day>header{padding:0 5px 10px!important;border:0!important;background:transparent!important}
.league-fixture-day>header h3{font-size:22px!important;letter-spacing:-.035em!important;color:var(--v60-ink)!important;text-transform:none!important}
.league-fixture-stack{gap:10px!important}
.league-fixture-pro-card{
  width:100%!important;max-width:100%!important;overflow:hidden!important;
  border:1px solid var(--v60-line)!important;border-radius:18px!important;background:#fff!important;
  box-shadow:0 7px 22px rgba(18,48,58,.035)!important;padding:15px 17px!important;
  transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease!important;
}
.league-fixture-pro-card:hover{border-color:#adddcb!important;box-shadow:var(--v60-shadow)!important;transform:translateY(-1px)!important}
.league-fixture-status>span{border-radius:999px!important;padding:5px 9px!important}
.league-fixture-club{min-width:0!important}
.league-fixture-club>div:last-child{min-width:0!important}
.league-fixture-club strong{white-space:normal!important;overflow-wrap:anywhere!important;color:var(--v60-ink)!important;line-height:1.18!important}
.league-club-logo{border-radius:13px!important;background:#fbfcfc!important;border:1px solid #e5ebe9!important}
.league-fixture-time b{font-family:"Inter Tight",Inter,sans-serif!important;font-size:19px!important;letter-spacing:-.02em!important;color:#0f2937!important}
.league-fixture-time span{font-size:8px!important;color:#9aa8a3!important}
.league-fixture-side{border-left:1px solid #edf1ef!important;padding-left:15px!important}
.league-fixture-ref,.league-fixture-venue{background:transparent!important;border:0!important;padding:2px 0!important}
.league-fixture-ref i,.league-fixture-venue i{width:32px;height:32px;border-radius:10px!important;background:var(--v60-mint)!important;display:grid!important;place-items:center!important;color:var(--v60-green)!important}
.league-fixture-odds span{border-radius:11px!important;background:#f7f9f8!important;border:1px solid #e4ebe8!important}
.league-fixture-open{height:42px!important;padding:0 13px!important;border-radius:12px!important;background:#eef8f4!important;color:var(--v60-green-deep)!important;display:flex!important;align-items:center!important;gap:8px!important;justify-content:center!important;white-space:nowrap!important}
.league-fixture-pro-card:hover .league-fixture-open{background:var(--v60-green)!important;color:#fff!important}

/* ====== MATCH CENTER ====== */
.fx-match-hero-pro{border-radius:20px!important;border:1px solid var(--v60-line)!important;box-shadow:var(--v60-shadow)!important;background:linear-gradient(135deg,#fff 0%,#f7fbf9 100%)!important;overflow:hidden!important}
.fx-tabs-five{border-radius:16px!important;overflow:hidden!important;border:1px solid var(--v60-line)!important;box-shadow:0 5px 18px rgba(18,48,58,.035)!important}
.fx-tabs-five button{min-width:0!important}
.fx-tabs-five button.active{background:var(--v60-ink)!important}
.fx-match-detail,.fx-browser{width:100%!important;max-width:100%!important;overflow:hidden!important}
.fx-player-grid,.fx-lineups-grid,.fx-player-streak-grid{min-width:0!important}
.fx-standings-wrap,.player-match-table{max-width:100%!important;overflow:auto!important}

/* ====== ANALIZADOR: puente con el próximo partido ====== */
#scannerNextFixture{
  margin:18px 18px 0!important;border:1px solid #dce8e3;border-radius:18px;background:linear-gradient(120deg,#ffffff 0%,#f3faf7 100%);
  box-shadow:0 10px 30px rgba(18,48,58,.055);overflow:hidden;
}
.scanner-next-inner{display:grid;grid-template-columns:minmax(160px,.72fr) minmax(420px,1.5fr) minmax(210px,.8fr);gap:18px;align-items:center;padding:16px 18px}
.scanner-next-label{display:flex;align-items:center;gap:11px;min-width:0}.scanner-next-label>i{width:40px;height:40px;display:grid;place-items:center;border-radius:12px;background:var(--v60-mint);color:var(--v60-green);font-size:16px}.scanner-next-label span{min-width:0}.scanner-next-label small{display:block;color:#84948e;font-size:9px;font-weight:900;letter-spacing:.10em}.scanner-next-label b{display:block;margin-top:3px;color:var(--v60-ink);font:800 13px/1.2 Inter,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.scanner-next-match{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:12px;align-items:center;min-width:0}.scanner-next-team{display:flex;align-items:center;gap:9px;min-width:0}.scanner-next-team.away{justify-content:flex-end;text-align:right}.scanner-next-team img{width:42px;height:42px;object-fit:contain;border-radius:11px;padding:4px;background:#fff;border:1px solid #e0e8e5}.scanner-next-team span{min-width:0}.scanner-next-team strong{display:block;color:var(--v60-ink);font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.scanner-next-team small{display:block;margin-top:3px;color:#8a9893;font-size:9px;font-weight:850}.scanner-next-kick{text-align:center;min-width:95px}.scanner-next-kick b{display:block;color:var(--v60-ink);font:900 18px/1 "Inter Tight",Inter,sans-serif}.scanner-next-kick small{display:block;margin-top:4px;color:#80908a;font-size:9px}.scanner-next-kick em{display:inline-block;margin-top:5px;padding:4px 7px;border-radius:999px;background:#e7f7f1;color:#087a5d;font-size:8px;font-style:normal;font-weight:900}
.scanner-next-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px}.scanner-next-actions button{height:42px;border-radius:12px;padding:0 13px;font:800 10px/1 Inter,sans-serif;cursor:pointer;white-space:nowrap}.scanner-next-context{border:1px solid #d8e5e0;background:#fff;color:#47625a}.scanner-next-open{border:1px solid var(--v60-green);background:var(--v60-green);color:#fff;box-shadow:0 8px 18px rgba(7,157,115,.15)}.scanner-next-open:hover{filter:brightness(.96)}
.scanner-next-empty{padding:14px 18px;display:flex;align-items:center;gap:10px;color:#70827b}.scanner-next-empty i{color:#97a7a1}.scanner-next-empty b{color:#314940;font-size:12px}.scanner-next-empty small{font-size:10px}

/* Sidebar menos “panel técnico” */
.inca-engine-card{border-radius:16px!important;border:1px solid #dce8e3!important;background:linear-gradient(145deg,#fff,#f5faf8)!important;box-shadow:0 7px 22px rgba(18,48,58,.04)!important}
.inca-engine-icon{border-radius:11px!important;background:var(--v60-mint)!important;color:var(--v60-green)!important}
.menu-option{border-radius:10px!important;margin:2px 7px!important;width:calc(100% - 14px)!important;transition:.15s ease!important}
.menu-option.active{background:#e8f7f1!important;color:#087b5e!important;box-shadow:inset 3px 0 0 var(--v60-green)!important}
.accordion-header{border-radius:11px!important;margin:3px 6px!important;width:calc(100% - 12px)!important}
.scanner-return{border-radius:11px!important}

/* ====== LOGIN: mismo lenguaje visual del producto ====== */
#incaAuthGate{
  padding:24px!important;background:
  radial-gradient(circle at 15% 10%,rgba(14,168,124,.12),transparent 34%),
  radial-gradient(circle at 88% 82%,rgba(16,44,59,.08),transparent 32%),
  #f4f7f6!important;color:var(--v60-ink)!important;
}
.inca-auth-shell{width:min(1040px,100%);display:grid;grid-template-columns:1.08fr .92fr;border:1px solid #dfe8e5;border-radius:28px;background:#fff;box-shadow:0 32px 90px rgba(18,48,58,.14);overflow:hidden}
.inca-auth-showcase{position:relative;min-height:560px;padding:54px 52px;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#102f3e 0%,#0d3e45 52%,#09664f 130%);color:#fff;overflow:hidden}
.inca-auth-showcase::after{content:"";position:absolute;width:320px;height:320px;border-radius:50%;right:-130px;bottom:-130px;border:1px solid rgba(255,255,255,.12);box-shadow:0 0 0 48px rgba(255,255,255,.025),0 0 0 96px rgba(255,255,255,.018)}
