}

body.scanner-active #scannerView .pj-stat-card{ 
    position: relative; 
    border-radius: 14px; 
    overflow: hidden; 
    background-size: cover; 
    background-position: center; 
    background-repeat: no-repeat; 
    min-height: 125px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    cursor: pointer; 
    
    /* 1. SE SECUESTRA EL TAMAÑO: No usamos border (que suma pixeles), usamos sombra interior */
    box-shadow: inset 0 0 0 0px transparent, 0 6px 15px rgba(0,0,0,0.15);
    
    /* 2. ACELERACIÓN HARDWARE */
    transform: translateZ(0); 
    
    /* 3. SOLO TRANSICIÓN EN LUCES Y SOMBRAS (Sin saltos de posición) */
    transition: box-shadow 0.2s ease, filter 0.2s ease; 
}

/* 4. BLOQUEO DE EVENTOS: Evita que el mouse se confunda al tocar el texto */
body.scanner-active #scannerView .pj-stat-overlay, body.scanner-active #scannerView .pj-stat-content{
    pointer-events: none;
}

body.scanner-active #scannerView .pj-stat-overlay{ 
