/* ========================================================================== */
/* INCA STATS V26 · MONOCHROME PRO + DARK THEME REBUILD                      */
/* ========================================================================== */

/* Brand system: black/white first. Semantic W/L/alerts keep their meaning. */
:root{
  --v26-black:#090909;
  --v26-black-2:#111214;
  --v26-black-3:#17191b;
  --v26-graphite:#232529;
  --v26-line:#2f3236;
  --v26-line-light:#dedede;
  --v26-paper:#ffffff;
  --v26-paper-2:#f6f6f5;
  --v26-ink:#0d0d0e;
  --v26-muted:#73777c;
}

/* Neutralize the old brand-green while leaving semantic result colors alone. */
body.theme-default,
body.theme-arquero,
body.theme-defensor,
body.theme-mediocentro,
body.theme-delantero{
  --brand-accent:#111214!important;
}
body.dark-mode.theme-default,
body.dark-mode.theme-arquero,
body.dark-mode.theme-defensor,
body.dark-mode.theme-mediocentro,
body.dark-mode.theme-delantero{
  --bg-deep:#090a0b!important;
  --bg-panel:#121315!important;
  --border-color:#303338!important;
  --text-primary:#f4f4f3!important;
  --text-muted:#9da1a6!important;
  --brand-accent:#f1f1ef!important;
}

/* Portal variables. */
.portal-shell{
  --p-bg:#f5f5f4!important;
  --p-surface:#fff!important;
  --p-card:#fff!important;
  --p-border:#dddddb!important;
